UPDATE questions SET stem = 'Which Group 2 metal has the lowest melting point?', why = 'The melting points are Be 1287 °C, Mg 650 °C, Ca 842 °C, Sr 777 °C and Ba 727 °C. Magnesium''s 650 °C is the lowest. Melting points do not fall smoothly down the group, because the packing of the metal atoms changes from one element to the next.', updated_at = unixepoch() * 1000 WHERE id = 'CHE-0716';
UPDATE questions SET stem = 'Down Group 2, the second ionization energy', why = 'The second ionization energies are Be 1757, Mg 1451, Ca 1145, Sr 1064 and Ba 965 kJ mol⁻¹. They fall down the group because the outer electron is further from the nucleus and better shielded, just as the first ionization energies do.', updated_at = unixepoch() * 1000 WHERE id = 'CHE-0718';
UPDATE questions SET stem = 'Which carbonate decomposes at about 900 °C?', why = 'Approximate decomposition temperatures are BeCO₃ 250 °C, MgCO₃ 540 °C, CaCO₃ 900 °C, SrCO₃ 1289 °C and BaCO₃ 1360 °C. The carbonate that breaks down at about 900 °C is CaCO₃, which matches the 900 to 1000 °C used in lime kilns.', updated_at = unixepoch() * 1000 WHERE id = 'CHE-0727';
