UPDATE questions SET stem = 'A non-protein organic molecule that binds loosely to an enzyme and is needed for it to work, such as NAD⁺, is called a', options = '["prosthetic group", "apoenzyme", "coenzyme", "substrate"]', why = 'Many enzymes need a non-protein helper. When the helper is an organic molecule that binds loosely and can leave the enzyme after the reaction, such as NAD⁺, it is a coenzyme. Many coenzymes are made from vitamins.', wrong = '{"0": "A prosthetic group is also non-protein, but it is bound tightly and permanently to the enzyme, like the haem group.", "1": "The apoenzyme is the protein part of the enzyme on its own, without its helper.", "3": "The substrate is the molecule the enzyme acts on, not a helper it needs to work."}', topic = 'Enzymes', difficulty = 'moderate', answer = 2, updated_at = unixepoch() * 1000 WHERE id = 'CHE-1044';
UPDATE questions SET stem = 'On a TLC plate run in one solvent, spot X has moved 2.0 cm and spot Y 5.0 cm from the baseline. Which statement is correct?', options = '["Y has the smaller Rf value.", "X is more soluble in the mobile phase than Y.", "X and Y must be the same compound.", "X is held more strongly by the stationary phase than Y."]', why = 'Both spots had the same solvent front, so the one that moved less has the smaller Rf. A substance moves slowly when it is adsorbed strongly on the stationary phase (silica gel or alumina) and spends less time in the moving solvent. So X is held more strongly than Y.', wrong = '{"0": "Y moved farther with the same solvent front, so Y has the larger Rf value.", "1": "A substance that dissolves better in the mobile phase travels farther. X travelled less, so it is less soluble in the mobile phase.", "2": "The same compound in the same solvent gives the same Rf. Different distances mean different compounds."}', topic = 'TLC', difficulty = 'moderate', answer = 3, updated_at = unixepoch() * 1000 WHERE id = 'CHE-1063';
UPDATE questions SET stem = 'Which correctly lists paper chromatography, thin-layer chromatography (TLC) and gas chromatography (GC) from slowest to fastest?', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1081';
UPDATE questions SET stem = 'An antacid tablet contains magnesium hydroxide. It relieves heartburn because it', options = '["kills the bacteria that produce the acid", "coats the food so that it is not digested", "neutralizes some of the excess hydrochloric acid in the stomach", "stops the stomach from making any acid at all"]', why = 'Magnesium hydroxide is a weak base. It neutralizes part of the excess stomach acid, Mg(OH)₂ + 2HCl → MgCl₂ + 2H₂O, which raises the pH and eases the burning feeling.', wrong = '{"0": "Stomach acid is made by cells of the stomach lining, not by bacteria. An antacid acts on the acid itself.", "1": "An antacid does not coat food or stop its digestion.", "3": "Antacids do not switch off acid production. Drugs called proton pump inhibitors do that."}', topic = 'Antacids', difficulty = 'easy', answer = 2, updated_at = unixepoch() * 1000 WHERE id = 'CHE-1183';
UPDATE questions SET stem = 'Many drugs that are amines are given as their hydrochloride salts (R–NH₃⁺ Cl⁻) mainly because the salts', options = '["cannot be broken down by the liver", "are stronger bases than the free amine", "contain more of the drug in each gram", "are more soluble in water, so they dissolve and are absorbed more easily"]', why = 'An amine reacts with HCl to form an ionic ammonium salt. Ions are hydrated well by water, so the salt dissolves far better than the neutral amine. This makes tablets and injections easier to prepare and helps the drug dissolve in the body.', wrong = '{"0": "Turning the drug into a salt does not stop the liver from breaking it down.", "1": "In the salt the amine is already protonated, so it is not a stronger base than the free amine.", "2": "The HCl adds mass, so a gram of the salt holds slightly less of the drug than a gram of the free amine."}', topic = 'Drug formulation', difficulty = 'moderate', answer = 3, updated_at = unixepoch() * 1000 WHERE id = 'CHE-1184';
