UPDATE questions SET stem = 'In the molecular orbital diagram of O₂, the 2p subshells give 6 electrons in bonding MOs (σ2pₓ, π2p_{y}, π2p_{z}) and 2 electrons in antibonding MOs. What is the bond order of O₂?', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1250';
UPDATE questions SET options = '["One each in the π*2p_{y} and π*2p_{z} antibonding orbitals", "Both in the σ2pₓ bonding orbital", "One each in the π2p_{y} and π2p_{z} bonding orbitals", "One in σ1s and one in σ*1s"]', why = 'After the bonding orbitals of O₂ are filled, two electrons remain for the antibonding π*2p_{y} and π*2p_{z} orbitals, which have equal energy. By Hund''s rule they enter these orbitals singly with parallel spins. These two unpaired electrons make oxygen paramagnetic.', wrong = '{"1": "Two electrons in one orbital must have opposite spins, so they would be paired, not unpaired.", "2": "The π2p_{y} and π2p_{z} bonding orbitals are completely filled in O₂, so their electrons are paired.", "3": "The σ1s and σ*1s orbitals are filled inner orbitals, each holding a pair of electrons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1251';
UPDATE questions SET options = '["In N₂ the π2p_{y} and π2p_{z} orbitals lie below σ2pₓ; in O₂ σ2pₓ lies below them.", "In N₂ σ2pₓ lies below the π2p orbitals; in O₂ it lies above them.", "The order is the same in both molecules.", "In N₂ the antibonding orbitals lie below the bonding orbitals."]', why = 'For N₂ the energy order of the 2p-derived orbitals is π2p_{y} = π2p_{z} < σ2pₓ, so the π orbitals are filled before σ2pₓ. For O₂ the order switches to σ2pₓ < π2p_{y} = π2p_{z}. So in N₂ the π orbitals lie below σ2pₓ, while in O₂ σ2pₓ lies below them.', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1252';
