UPDATE questions SET why = 'Two rules apply to equilibrium constants. Reversing an equation gives 1/K. Multiplying all coefficients by ½ raises K to the power ½, which is a square root. Doing both gives K′ = (1/K)^{½} = 1/√K.', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7068';
