UPDATE questions SET stem = 'Choose the word closest in meaning to AMIABLE.', options = '["Friendly", "Lazy", "Anxious", "Strange"]', why = 'Amiable means pleasant, good-natured and easy to like, the same as friendly.', wrong = '{"1": "Lazy describes being unwilling to work, not a pleasant manner.", "2": "Anxious means worried or nervous.", "3": "Strange means unusual or unfamiliar."}', topic = 'Word meanings', difficulty = 'moderate', answer = 0, updated_at = unixepoch() * 1000 WHERE id = 'LR-1122';
UPDATE questions SET stem = 'Choose the word most nearly opposite in meaning to LENIENT.', options = '["Kind", "Gentle", "Tolerant", "Strict"]', why = 'Lenient means not strict: allowing more freedom, or giving a lighter punishment than expected. Its opposite is strict.', wrong = '{"0": "A lenient person is often kind, so this is close in meaning, not opposite.", "1": "Gentle is close in meaning to lenient.", "2": "Tolerant means nearly the same as lenient."}', topic = 'Word meanings', difficulty = 'moderate', answer = 3, updated_at = unixepoch() * 1000 WHERE id = 'LR-1123';
UPDATE questions SET stem = 'Choose the word closest in meaning to INEVITABLE.', options = '["Unlikely", "Sudden", "Unavoidable", "Unexpected"]', why = 'Inevitable means certain to happen and impossible to prevent, the same as unavoidable.', wrong = '{"0": "Unlikely means probably will not happen, nearly the opposite.", "1": "Sudden is about how quickly something happens, not whether it can be avoided.", "3": "An inevitable event is often expected. Unexpected means not foreseen."}', topic = 'Word meanings', difficulty = 'hard', answer = 2, updated_at = unixepoch() * 1000 WHERE id = 'LR-1124';
UPDATE questions SET why = 'Write every term as a power of 2: 4³ = (2²)³ = 2⁶ and 8³ = (2³)³ = 2⁹. Then 2⁵ × 2⁶ ÷ 2⁹ = 2^{5 + 6 − 9} = 2² = 4. Add exponents when multiplying and subtract them when dividing.', wrong = '{"1": "2 comes from taking 4³ as 2⁵ instead of 2⁶: 2^{5 + 5 − 9} = 2¹.", "2": "1 comes from taking 4³ as 2⁴, adding 1 to the exponent instead of multiplying: 2^{5 + 4 − 9} = 2⁰ = 1.", "3": "8 comes from taking 8³ as 2⁸ instead of 2⁹: 2^{5 + 6 − 8} = 2³."}', updated_at = unixepoch() * 1000 WHERE id = 'MAT-0022';
UPDATE questions SET stem = 'What is 27^{2/3}?', why = 'In a fractional index, the denominator is a root and the numerator is a power. So 27^{2/3} = (∛27)² = 3² = 9. Taking the root first keeps the numbers small.', wrong = '{"0": "18 multiplies 27 by 2/3. An index is not a multiplier.", "1": "3 is 27^{1/3}, the cube root only. It still needs to be squared.", "2": "729 is 27², squaring without taking the cube root."}', updated_at = unixepoch() * 1000 WHERE id = 'MAT-0085';
UPDATE questions SET stem = 'Solve 4^{x + 1} = 32.', why = 'Write both sides as powers of 2: 4^{x + 1} = (2²)^{x + 1} = 2^{2x + 2} and 32 = 2⁵. Equal bases mean equal powers: 2x + 2 = 5, so x = 3/2. Check: 4^{5/2} = (√4)⁵ = 2⁵ = 32.', wrong = '{"0": "x = 7 treats 4^{x + 1} as 4(x + 1) = 32. The x + 1 is a power, not a multiplier.", "1": "x = 4 writes 4^{x + 1} as 2^{x + 1}. Since 4 = 2², the exponent doubles to 2x + 2.", "3": "x = 5/2 solves 2x = 5, dropping the +2 from 2x + 2 = 5."}', updated_at = unixepoch() * 1000 WHERE id = 'MAT-0086';
UPDATE questions SET why = 'Each term is double the last, so this is a geometric sequence with a = 3 and r = 2. The nth term is ar^{n − 1}, so T₆ = 3 × 2⁵ = 3 × 32 = 96. Listing: 3, 6, 12, 24, 48, 96.', updated_at = unixepoch() * 1000 WHERE id = 'MAT-0190';
UPDATE questions SET why = 'log_{b} y asks what power of b gives y. 2³ = 8, so log₂ 8 = 3. 3⁻² = 1/9, so log₃ (1/9) = −2. 10⁻³ = 0.001, so log₁₀ 0.001 = −3. Total = 3 − 2 − 3 = −2.', updated_at = unixepoch() * 1000 WHERE id = 'MAT-0333';
UPDATE questions SET stem = 'Simplify 27^{2/3} × 16^{−3/4}.', why = 'A fractional power a^{m/n} means the nth root of a, raised to the power m. 27^{2/3} = (∛27)² = 3² = 9. A negative power means a reciprocal: 16^{−3/4} = 1/(⁴√16)³ = 1/2³ = 1/8. Product = 9 × 1/8 = 9/8.', wrong = '{"0": "72 = 9 × 8 ignores the negative sign in the power, which turns 8 into 1/8.", "1": "8/9 turns the whole answer upside down. Only the 16 part is a reciprocal.", "3": "3/2 = 3 × 1/2 uses only the roots, 27^{1/3} × 16^{−1/4}, and forgets the powers 2 and 3."}', updated_at = unixepoch() * 1000 WHERE id = 'MAT-0340';
UPDATE questions SET why = 'In three dimensions <v²> = <vₓ²> + <v_{y}²> + <v_{z}²>. Because the motion is random with no preferred direction, the three components are equal on average, so <v²> = 3<vₓ²> and <vₓ²> = <v²>/3. This is where the ⅓ in P = ⅓ρ<v²> comes from.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0010';
UPDATE questions SET why = 'From P = ⅓ρ<v²>, the mean-square speed is <v²> = 3P/ρ = (3 × 1.2 × 10⁵) ÷ 1.6 = 2.25 × 10⁵ m² s⁻². The rms speed is its square root: v_{rms} = √(2.25 × 10⁵) ≈ 474 m s⁻¹. Note that the pressure must be in pascals and density in kg m⁻³ for SI units.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0013';
UPDATE questions SET options = '["(1/2)k_{B}T", "(2/3)k_{B}T", "(3/2)k_{B}T", "3k_{B}T"]', why = 'Kinetic theory gives PV = ⅓Nm<v²>, and the gas law gives PV = Nk_{B}T. Setting them equal gives ⅓m<v²> = k_{B}T, so the average translational kinetic energy is ½m<v²> = (3/2)k_{B}T.', wrong = '{"0": "½k_{B}T is the average energy for motion along one direction only. Translation in three directions gives three times this.", "1": "⅔ is the factor in P = ⅔(N/V)<K.E.>. It is not the factor in front of k_{B}T for the kinetic energy.", "3": "3k_{B}T equals m<v²>, which is twice the kinetic energy ½m<v²>."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0014';
UPDATE questions SET stem = 'What is the average translational kinetic energy of a gas molecule at 300 K? (k_{B} = 1.38 × 10⁻²³ J K⁻¹)', why = 'The average translational kinetic energy of a gas molecule is <K.E.> = (3/2)k_{B}T. Substituting: 1.5 × 1.38 × 10⁻²³ J K⁻¹ × 300 K = 6.21 × 10⁻²¹ J. This tiny value is typical of the energy of a single molecule at room temperature.', wrong = '{"0": "2.07 × 10⁻²¹ J is ½k_{B}T, the share of energy for one direction of motion only.", "1": "4.14 × 10⁻²¹ J is k_{B}T alone. The factor 3/2 has been left out.", "3": "1.24 × 10⁻²⁰ J is 3k_{B}T, which is twice the correct average kinetic energy."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0015';
UPDATE questions SET why = 'Kinetic theory shows that <K.E.> = (3/2)k_{B}T. The average translational kinetic energy of the molecules is directly proportional to the absolute temperature, so temperature is a direct measure of how fast, on average, the molecules are moving.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0016';
UPDATE questions SET why = 'The average translational kinetic energy, (3/2)k_{B}T, depends only on temperature, so it is the same for helium and oxygen. Since ½mv²_rms is equal for both, the lighter helium atom must have the larger rms speed, about four times that of oxygen.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0017';
UPDATE questions SET why = 'The rms speed is v_{rms} = √(3k_{B}T/m), so for a given gas v_{rms} ∝ √T. Making the absolute temperature four times larger multiplies the speed by √4 = 2, so the new rms speed is 2v.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0018';
UPDATE questions SET stem = 'Gas X has a molecular mass four times that of gas Y. At the same temperature, the ratio v_{rms}(X) : v_{rms}(Y) is', why = 'At a fixed temperature v_{rms} = √(3k_{B}T/m), so v_{rms} ∝ 1/√m. With m_{X} = 4m_{Y}, v_{rms}(X)/v_{rms}(Y) = √(m_{Y}/m_{X}) = √(1/4) = 1/2. The heavier gas X moves at half the speed, a ratio of 1 : 2.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0019';
UPDATE questions SET stem = 'What is the rms speed of nitrogen molecules (28 u) at 300 K? (k_{B} = 1.38 × 10⁻²³ J K⁻¹, 1 u = 1.66 × 10⁻²⁷ kg)', why = 'Mass of one molecule: m = 28 × 1.66 × 10⁻²⁷ = 4.65 × 10⁻²⁶ kg. Then v_{rms} = √(3k_{B}T/m) = √(3 × 1.38 × 10⁻²³ × 300 ÷ 4.65 × 10⁻²⁶) = √(2.67 × 10⁵) ≈ 517 m s⁻¹. Lighter molecules or higher temperatures would give larger rms speeds.', wrong = '{"0": "299 m s⁻¹ is √(k_{B}T/m). The factor 3 in v_{rms} = √(3k_{B}T/m) is missing.", "1": "422 m s⁻¹ is √(2k_{B}T/m), which uses 2 in place of 3 in the rms speed formula.", "3": "2.7 × 10⁵ m² s⁻² is the mean-square speed <v²>. Its square root gives the rms speed."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0020';
UPDATE questions SET why = 'Using v_{rms} = √(3k_{B}T/m) at about 298 K gives roughly 481 m s⁻¹ for oxygen and 515 m s⁻¹ for nitrogen. Both are greater than the speed of sound in air, about 340 m s⁻¹, so the molecules move faster than sound travels through them.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0021';
UPDATE questions SET stem = 'The Boltzmann constant k_{B} is related to the general gas constant R and Avogadro''s number N_{A} by', options = '["k_{B} = R × N_{A}", "k_{B} = N_{A}/R", "k_{B} = R + N_{A}", "k_{B} = R/N_{A}"]', why = 'The gas law for n moles, PV = nRT, and for N molecules, PV = Nk_{B}T, give R = N_{A} k_{B}. So k_{B} = R/N_{A} = 8.31 ÷ (6.02 × 10²³) ≈ 1.38 × 10⁻²³ J K⁻¹. The Boltzmann constant is simply the gas constant per molecule.', wrong = '{"0": "R × N_{A} would be about 5 × 10²⁴, a huge number, not the tiny 1.38 × 10⁻²³ J K⁻¹.", "1": "N_{A}/R inverts the relationship and gives about 7 × 10²², not 1.38 × 10⁻²³.", "2": "R and N_{A} have different units, so they cannot be added."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0022';
UPDATE questions SET stem = 'Using PV = Nk_{B}T, how many gas molecules are there per cubic metre at a pressure of 1.01 × 10⁵ Pa and a temperature of 300 K? (k_{B} = 1.38 × 10⁻²³ J K⁻¹)', why = 'From PV = Nk_{B}T, the number of molecules per unit volume is N/V = P/(k_{B}T). Substituting: 1.01 × 10⁵ ÷ (1.38 × 10⁻²³ × 300) = 1.01 × 10⁵ ÷ 4.14 × 10⁻²¹ ≈ 2.4 × 10²⁵ molecules per m³.', wrong = '{"0": "2.4 × 10²³ has the right digits but the power of ten is off by a factor of 100.", "2": "6.0 × 10²³ is Avogadro''s number, the number of particles in one mole, not the number per cubic metre here.", "3": "7.3 × 10²⁷ is P/k_{B} alone. It forgets to divide by the temperature of 300 K."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0023';
UPDATE questions SET stem = 'The book quotes the Boltzmann constant as 8.62 × 10⁻⁵ eV K⁻¹. What is k_{B}T at room temperature (300 K) in electronvolts?', why = 'With k_{B} = 8.62 × 10⁻⁵ eV K⁻¹, the thermal energy at 300 K is k_{B}T = 8.62 × 10⁻⁵ × 300 ≈ 0.026 eV. Such small energies are awkward in joules, which is why the electronvolt is convenient. A handy fact: k_{B}T at room temperature is about 1/40 eV.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0024';
UPDATE questions SET stem = 'According to the Boltzmann distribution law, N₂/N₁ = e^{−ΔE/k_{B}T}, where N₂ is the population of the higher energy level. This means that in thermal equilibrium', why = 'For a higher level, ΔE is positive, so the exponent −ΔE/k_{B}T is negative and e^{−ΔE/k_{B}T} is less than 1. Then N₂/N₁ < 1, meaning N₂ < N₁. In thermal equilibrium more particles occupy the lower energy level than the higher one.', wrong = '{"0": "The exponential factor is below 1, so the higher level holds fewer particles. More in the upper level would be a population inversion.", "1": "Equal populations would need e^{−ΔE/k_{B}T} = 1, which happens only if ΔE = 0.", "2": "The factor e^{−ΔE/k_{B}T} is small but never zero, so some particles always occupy the higher level."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0027';
UPDATE questions SET stem = 'Two energy levels are separated by an energy exactly equal to k_{B}T. By the Boltzmann distribution law, the ratio of the population of the upper level to that of the lower level is about', why = 'The Boltzmann law gives N₂/N₁ = e^{−ΔE/k_{B}T}. With ΔE = k_{B}T, the exponent is −1, so N₂/N₁ = e⁻¹ = 1/2.718 ≈ 0.37. The upper level holds a little over a third as many particles as the lower one.', wrong = '{"1": "2.72 is e⁺¹. The exponent is negative, so the upper level must have fewer particles, giving a ratio below 1.", "2": "A ratio of 1.00 would need ΔE = 0, since e⁰ = 1. Then both levels would have the same energy.", "3": "0.50 would need ΔE = k_{B}T ln 2 ≈ 0.69 k_{B}T, not ΔE = k_{B}T."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0028';
UPDATE questions SET stem = 'In the hydrostatic equation for a star, ΔP/Δr = −GM_{r}ρ_{r}/r², what does the negative sign show?', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0031';
UPDATE questions SET why = 'In SHM the speed is v = ω√(x₀² − x²). This is largest when x = 0, at the mean position, where v_{max} = x₀ω. Here all the energy is kinetic, while the restoring force and acceleration are zero.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0065';
UPDATE questions SET why = 'Maximum speed occurs at the mean position: v_{max} = x₀ω = 0.05 × 20 = 1.0 m s⁻¹. Maximum acceleration occurs at the extreme positions: a_{max} = x₀ω² = 0.05 × 400 = 20 m s⁻².', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0068';
UPDATE questions SET why = 'The m-th bright fringe is at y_{m} = mλL/d from the centre. Substituting: y₃ = 3 × 500 × 10⁻⁹ × 2.0 ÷ (0.50 × 10⁻³) = 6.0 × 10⁻³ m = 6.0 mm. The fringe spacing is 2.0 mm, and the third bright fringe is three spacings out.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0116';
UPDATE questions SET why = 'The capacitance of an isolated sphere is C = 4πε₀ε_{r}R, which depends only on its radius and the surrounding medium. A larger sphere can hold more charge at the same surface potential. Adding charge raises V in proportion, so Q/V, the capacitance, stays the same.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0154';
UPDATE questions SET why = 'Filling the gap with a dielectric multiplies the capacitance by its relative permittivity: C = ε_{r} × C_{air}. Substituting: C = 5 × 4 μF = 20 μF. The dielectric lets the capacitor store more charge at the same voltage.', wrong = '{"0": "0.8 μF divides 4 μF by ε_{r}. A dielectric increases capacitance, it does not reduce it.", "1": "9 μF adds ε_{r} to the capacitance (4 + 5). The relative permittivity is a multiplying factor.", "3": "4 μF is the original value in air. Inserting a dielectric changes it."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0158';
UPDATE questions SET why = 'The dielectric constant ε_{r} is the ratio of the capacitance with the material filling the space between the plates to the capacitance with vacuum there: ε_{r} = C_{med}/C_{vac}. Since an insulator always raises the capacitance, ε_{r} is greater than 1.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0159';
UPDATE questions SET why = 'Capacitors in parallel all have the same voltage, and the total charge is the sum of their charges. So their capacitances simply add: C_{e} = C₁ + C₂ + C₃ = 2 + 3 + 5 = 10 μF. The parallel combination is larger than any single capacitor.', wrong = '{"0": "0.97 μF is the series result, from 1/C_{e} = 1/2 + 1/3 + 1/5 = 31/30.", "1": "30 μF comes from multiplying the three values. Capacitances in parallel add.", "3": "3.3 μF is the average of the three values, which is not how capacitors combine."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0162';
UPDATE questions SET why = 'For capacitors in series, 1/C_{e} = 1/C₁ + 1/C₂ = 1/6 + 1/3 = 1/6 + 2/6 = 3/6. So C_{e} = 6/3 = 2 μF. A series combination is always smaller than the smallest capacitor in it.', wrong = '{"1": "9 μF (6 + 3) is the parallel result, where capacitances add directly.", "2": "4.5 μF is the average of 6 and 3, which is not how capacitors combine.", "3": "18 μF is the product 6 × 3. For two in series, C_{e} = product ÷ sum = 18 ÷ 9 = 2 μF."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0164';
UPDATE questions SET why = 'The series capacitance is C_{e} = (6 × 3)/(6 + 3) = 2 μF. The charge on each capacitor is Q = C_{e}V = 2 μF × 12 V = 24 μC. Across the 3 μF capacitor, V = Q/C = 24 μC ÷ 3 μF = 8 V, and the other 4 V is across the 6 μF capacitor.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0165';
UPDATE questions SET why = 'In parallel, C_{e} = 2C, so the energy is ½(2C)V² = CV². In series, C_{e} = C/2, so the energy is ½(C/2)V² = CV²/4. Dividing: CV² ÷ (CV²/4) = 4. The parallel connection stores four times as much energy.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0171';
UPDATE questions SET why = 'The charge on a charging capacitor is q = q₀(1 − e^{−t/RC}). At t = RC this gives q = q₀(1 − e⁻¹) = q₀(1 − 0.37) ≈ 0.63 q₀. So the time constant is the time taken to reach 63% of the final charge.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0174';
UPDATE questions SET why = 'During discharge, Q = Q₀e^{−t/RC}. At t = 2RC, Q = Q₀e⁻² ≈ 0.135 Q₀, about 0.14 of the initial charge. Each time constant multiplies the charge by 0.37, so after two it is 0.37 × 0.37 ≈ 0.14.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0175';
UPDATE questions SET why = 'During discharge the charge, voltage and current all follow the same law: Q = Q₀e^{−t/RC}, V = V₀e^{−t/RC} and I = I₀e^{−t/RC}. The current is largest at the start and falls quickly at first, then more and more slowly.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0177';
UPDATE questions SET why = 'In full-wave rectification every half-cycle points the same way, so the average is the half-cycle average of a sine wave: I_{av} = (2/π)I₀ = 0.637 I₀. Substituting: I_{av} = 0.637 × 10 A = 6.37 A.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0189';
UPDATE questions SET why = 'The peak-to-peak value is the difference between the positive peak and the negative peak. For a symmetrical sine wave this is twice the peak value: V_{p-p} = 2V₀ = 2 × 12 V = 24 V.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0190';
UPDATE questions SET why = 'The rms (root-mean-square) or effective value is the steady direct current that would produce heat in a resistor at the same rate as the alternating current. For a sine wave it is I_{rms} = I₀/√2 = 0.707 I₀.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0191';
UPDATE questions SET why = 'Comparing with I = I₀ sin ωt gives I₀ = 10 A and ω = 314 rad s⁻¹. The rms value is I_{rms} = I₀/√2 = 10 × 0.707 = 7.07 A. The frequency is f = ω/2π = 314 ÷ 6.28 ≈ 50 Hz, the mains frequency.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0192';
UPDATE questions SET why = 'Mains voltages are quoted as rms values. For a sine wave the peak is V₀ = √2 × V_{rms} = 1.414 × 220 V ≈ 311 V. So the supply actually swings between about +311 V and −311 V in every cycle.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0193';
UPDATE questions SET why = 'The maximum power is V₀²/R = 100² ÷ 20 = 500 W. For a sine wave the mean power is half of this, 250 W. The same result comes from the rms voltage: V_{rms}²/R = (70.7)² ÷ 20 ≈ 250 W.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0195';
UPDATE questions SET why = 'The reactance of an inductor is X_{L} = 2πfL = ωL. Substituting: X_{L} = 2 × 3.14 × 50 × 0.20 ≈ 62.8 Ω, about 63 Ω. X_{L} grows with frequency, which is why inductors block high frequencies more.', wrong = '{"1": "10 Ω is f × L = 50 × 0.20. The factor 2π in X_{L} = 2πfL is missing.", "2": "0.016 Ω is 1/(2πfL), using a reciprocal form like a capacitor''s reactance by mistake.", "3": "31 Ω is πfL. The factor 2 in X_{L} = 2πfL has been left out."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0200';
UPDATE questions SET why = 'Inductive reactance is X_{L} = 2πfL, which is directly proportional to frequency. For DC, f = 0, so X_{L} = 0 and the coil offers no reactance, only its small wire resistance. As the frequency rises, X_{L} rises in proportion, so a coil passes DC easily but opposes high-frequency AC.', wrong = '{"0": "Infinite for DC and decreasing with frequency describes a capacitor''s reactance, X_{C} = 1/(2πfC).", "2": "X_{L} = 2πfL depends directly on f, so doubling the frequency doubles the reactance.", "3": "Reactance comes from the coil''s inductance and depends on frequency. Resistance comes from the wire and does not."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0201';
UPDATE questions SET options = '["equal to V_{rms} × I_{rms}", "half of V₀I₀", "zero, because the energy stored in its magnetic field is returned to the source each cycle", "maximum at resonance"]', why = 'In a pure inductor, current lags voltage by 90°. In one quarter cycle the source supplies energy to build up the magnetic field, and in the next quarter the collapsing field returns it. Over a full cycle the net energy taken is zero, so the average power is zero: P = V_{rms} I_{rms} cos 90° = 0.', wrong = '{"0": "V_{rms} × I_{rms} is the apparent power. The true power includes cos 90° = 0, so it is zero.", "1": "½V₀I₀ is the mean power in a resistor, where voltage and current are in phase.", "3": "A pure inductor dissipates no power at any frequency. Resonance belongs to circuits with both L and C."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0202';
UPDATE questions SET why = 'First find the reactance: X_{L} = 2πfL = 2 × 3.14 × 100 × 0.50 ≈ 314 Ω. With negligible resistance, Ohm''s law for AC gives V_{rms} = I_{rms} X_{L} = 0.020 A × 314 Ω ≈ 6.3 V.', wrong = '{"0": "1.0 V is I × f × L = 0.020 × 100 × 0.50. The factor 2π in X_{L} is missing.", "1": "314 is the reactance in ohms. It must be multiplied by the current to give the voltage.", "2": "6.4 × 10⁻⁵ V comes from dividing the current by the reactance instead of multiplying."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0203';
UPDATE questions SET why = 'Capacitive reactance is X_{C} = 1/(2πfC). Substituting: X_{C} = 1 ÷ (2 × 3.14 × 50 × 50 × 10⁻⁶) = 1 ÷ 0.0157 ≈ 63.7 Ω, about 64 Ω. A larger capacitance or a higher frequency would give a smaller reactance.', wrong = '{"0": "0.016 is 2πfC, the reciprocal of the reactance. It must be inverted.", "1": "127 Ω is 1/(πfC). The factor 2 in 2πfC has been left out.", "2": "400 Ω is 1/(fC). The factor 2π in X_{C} = 1/(2πfC) has been left out."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0207';
UPDATE questions SET why = 'Capacitive reactance is X_{C} = 1/(2πfC), which is inversely proportional to frequency. At a higher frequency the plates charge and discharge more often, so more charge flows per second. The reactance falls and the current increases.', wrong = '{"1": "Reactance rising with frequency is how an inductor behaves, not a capacitor.", "2": "X_{C} = 1/(2πfC) depends on f, so changing the frequency changes the reactance.", "3": "X_{C} is infinite only for DC, where f = 0. Increasing f makes it smaller."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0208';
UPDATE questions SET why = 'For DC, f = 0, so X_{C} = 1/(2πfC) is infinite. Once the plates are charged no steady current flows, so DC is blocked. With AC the plates keep charging and discharging in opposite directions, so an alternating current flows in the circuit.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0209';
UPDATE questions SET why = 'Impedance Z is the total opposition of an AC circuit to current, defined as Z = V_{rms}/I_{rms}. Substituting: Z = 220 V ÷ 4.0 A = 55 Ω. Like resistance, it is measured in ohms.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0210';
UPDATE questions SET why = 'The voltage across the capacitor is 90° out of phase with the voltage across the resistor, so R and X_{C} add like the sides of a right-angled triangle. Z = √(R² + X_{C}²) = √(30² + 40²) = √(900 + 1600) = √2500 = 50 Ω.', wrong = '{"0": "70 Ω adds R and X_{C} directly, ignoring the 90° phase difference between their voltages.", "1": "10 Ω subtracts them. Also, the impedance can never be less than the 30 Ω resistance alone.", "2": "24 Ω is R × X_{C} ÷ 50, not a valid series formula. It is also less than R, which is impossible."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0211';
UPDATE questions SET stem = 'In an RC series circuit with R = X_{C}, the current', why = 'In an RC series circuit, the phase angle is given by tan θ = X_{C}/R. With R = X_{C}, tan θ = 1, so θ = 45°. Because the circuit is capacitive, the current leads the applied voltage by 45°.', wrong = '{"1": "Current lags the voltage in an inductive (RL) circuit, not in an RC circuit.", "2": "A full 90° lead happens only in a pure capacitor, with no resistance at all.", "3": "Current and voltage would be in phase only if X_{C} were zero, making the circuit purely resistive."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0212';
UPDATE questions SET why = 'The impedance is Z = √(R² + X_{L}²) = √(6² + 8²) = √100 = 10 Ω. The phase angle is given by tan θ = X_{L}/R = 8/6, so θ ≈ 53°. In an inductive (RL) circuit the current lags behind the voltage.', wrong = '{"0": "14 Ω adds R and X_{L} directly, ignoring phase. Also, in an inductive circuit the current lags, not leads.", "2": "The impedance is right, but the current lags in an RL circuit, and tan θ = 8/6 gives 53°, not 37°.", "3": "2 Ω subtracts R and X_{L}, and with an inductor present the current cannot be in phase."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0213';
UPDATE questions SET why = 'The real power in an AC circuit is P = V_{rms} I_{rms} cos θ, where cos θ is the power factor. Substituting: P = 220 V × 5.0 A × 0.80 = 880 W. The full 1100 VA is not all used as real power.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0214';
UPDATE questions SET why = 'Efficiency is the fraction of input power delivered as useful output. An inverter changes the panel''s DC into AC, and at 90% efficiency the AC output is P_{AC} = 0.90 × 500 W = 450 W. The other 50 W is lost, mostly as heat.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0216';
UPDATE questions SET why = 'V_{L} and V_{C} are 180° out of phase, so their net is V_{L} − V_{C} = 60 − 20 = 40 V. This is at 90° to V_{R}, so they combine like a right triangle: V = √(V_{R}² + (V_{L} − V_{C})²) = √(30² + 40²) = √2500 = 50 V.', wrong = '{"0": "110 V adds all three voltages directly, ignoring their phase differences.", "2": "70 V adds V_{R} and the net reactive voltage directly, ignoring the 90° between them.", "3": "90 V adds V_{R} and V_{L} and leaves out the capacitor voltage completely."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0217';
UPDATE questions SET options = '["X_{L} = X_{C}, the impedance is maximum and the current is minimum", "the current lags the voltage by 90°", "X_{L} = X_{C}, the impedance is minimum (Z = R) and the current is maximum", "the power factor is zero"]', why = 'At resonance X_{L} = X_{C}, so the two reactances cancel and the impedance reduces to Z = R, its smallest possible value. The current is therefore largest. Voltage and current are in phase, so the power factor is 1.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0218';
UPDATE questions SET why = 'The resonant frequency is f = 1/(2π√(LC)). Here LC = (10 × 10⁻³)(10 × 10⁻⁶) = 1.0 × 10⁻⁷, so √(LC) = 3.16 × 10⁻⁴ s. Then f = 1 ÷ (2π × 3.16 × 10⁻⁴) ≈ 503 Hz, where X_{L} and X_{C} are equal.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0219';
UPDATE questions SET options = '["an RC circuit, because X_{C} is much larger than X_{L}", "an RL circuit, because X_{L} is much larger than X_{C}", "a pure resistor", "an open circuit"]', why = 'X_{L} = ωL grows with frequency, while X_{C} = 1/ωC shrinks. Well above resonance, X_{L} is much larger than X_{C}, so the inductive reactance dominates. The circuit then behaves mainly like an RL circuit, with the current lagging the voltage.', wrong = '{"0": "X_{C} is larger than X_{L} at frequencies below resonance, not above it.", "2": "The circuit behaves as a pure resistor only at resonance, where X_{L} = X_{C}.", "3": "Current still flows. The impedance is large but finite, so it is not an open circuit."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0221';
UPDATE questions SET why = 'At resonance only R limits the current, so the current can be large. The voltages I X_{L} and I X_{C} can each be much larger than the source voltage. They are 180° out of phase, so they cancel each other, and the whole source voltage appears across R.', wrong = '{"0": "A current flows through L and C, so the voltages across them, I X_{L} and I X_{C}, are not zero.", "1": "The two voltages are 180° apart, so they cancel rather than add up.", "3": "Each equals I X_{L}, which depends on the current and reactance and can be far larger than the applied voltage."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0222';
UPDATE questions SET stem = 'Using V_{ripple} = I/(2fC), what is the ripple voltage of a 50 Hz full-wave rectifier with a 1000 μF smoothing capacitor and a load current of 0.50 A?', why = 'Substitute into V_{ripple} = I/(2fC): V_{ripple} = 0.50 A ÷ (2 × 50 Hz × 1000 × 10⁻⁶ F) = 0.50 ÷ 0.10 = 5.0 V. A larger capacitor or smaller load current would give a smaller ripple.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0233';
UPDATE questions SET why = 'The emf induced in the secondary coil is proportional to the rate of change of current in the primary: ε_{s} = M ΔI_{p}/Δt. Substituting: ε_{s} = 0.50 H × 40 A s⁻¹ = 20 V. A steady primary current would induce no emf at all.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0241';
UPDATE questions SET why = 'The Paschen series follows 1/λ = R_{H}(1/3² − 1/n²) with n = 4, 5, 6, …, so every transition ends on the level n = 3. These energy jumps are smaller than in the Lyman and Balmer series, so the lines are in the infrared.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0282';
UPDATE questions SET why = 'When an electron drops from a higher level to a lower one, the photon carries away the energy difference: hf = E_{upper} − E_{lower}. Here hf = −1.51 − (−3.40) = 1.89 eV. This photon forms the red line of the Balmer series.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0284';
UPDATE questions SET why = 'A photon is absorbed completely or not at all, so its energy must exactly equal the energy difference E_{upper} − E_{lower}. A colliding electron can give up just part of its kinetic energy and keep the rest, so it only needs kinetic energy equal to or greater than the difference.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0286';
UPDATE questions SET why = 'The mass of a nucleus is always less than the total mass of its separate protons and neutrons. The difference, Δm = Zm_{p} + Nm_{n} − M_{nucleus}, is called the mass defect. This missing mass corresponds to the binding energy released when the nucleus formed.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0293';
UPDATE questions SET stem = 'The number of undecayed nuclei is N = N₀e^{−λt}. After a time t = 1/λ (one mean life), the fraction remaining is about', why = 'Substituting t = 1/λ into N = N₀e^{−λt} gives N = N₀e^{−1}. Since e ≈ 2.718, e^{−1} ≈ 0.37. So after one mean life about 37% of the nuclei remain undecayed and about 63% have decayed.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0329';
UPDATE questions SET why = 'The shortest wavelength comes from an electron that gives all its energy eV to one photon, so eV = hc/λ_{min} and λ_{min} = hc ÷ eV. Substituting, λ_{min} = (6.63 × 10⁻³⁴ × 3 × 10⁸) ÷ (1.6 × 10⁻¹⁹ × 25 000) = 1.99 × 10⁻²⁵ ÷ 4.0 × 10⁻¹⁵ ≈ 5.0 × 10⁻¹¹ m.', wrong = '{"0": "5.0 × 10⁻⁸ m uses 25 V instead of 25 kV, giving a wavelength 1000 times too long.", "1": "2.5 × 10⁻¹¹ m is the cut-off for a 50 kV tube. Doubling the voltage by mistake halves λ_{min}.", "3": "1.2 × 10⁻⁶ m is hc/e alone. The voltage of 25 000 V has not been divided in."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0362';
UPDATE questions SET why = 'The cut-off wavelength comes from electrons giving all their energy to one photon, so eV = hc/λ_{min} and λ_{min} = hc/eV. This means λ_{min} is inversely proportional to V. If the voltage is doubled, each electron has twice the energy and λ_{min} is halved.', wrong = '{"0": "A higher voltage gives more energetic photons, which have shorter wavelengths. λ_{min} falls, it does not double.", "1": "The cut-off depends directly on the accelerating voltage through λ_{min} = hc/eV, so it does change.", "2": "λ_{min} varies as 1/V, not 1/V². Doubling V makes it two times smaller, not four times smaller."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0363';
UPDATE questions SET why = 'The highest frequency photon carries all the electron''s energy, so hf_{max} = eV and f_{max} = eV ÷ h. Substituting, f_{max} = (1.6 × 10⁻¹⁹ × 20 000) ÷ 6.63 × 10⁻³⁴ = 3.2 × 10⁻¹⁵ ÷ 6.63 × 10⁻³⁴ ≈ 4.8 × 10¹⁸ Hz.', wrong = '{"1": "4.8 × 10¹⁵ Hz uses 20 V instead of 20 kV, giving a frequency 1000 times too small.", "2": "About 2.1 × 10⁻¹⁹ comes from dividing h by eV, the reciprocal of the correct expression.", "3": "6.2 × 10⁻¹¹ m is the matching minimum wavelength, c ÷ f_{max}. It is a length, not a frequency."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0364';
UPDATE questions SET why = 'An electron that loses all its kinetic energy eV in a single collision produces one photon of the greatest possible energy, hf_{max} = eV. The greatest energy means the shortest wavelength, λ_{min}. Electrons that lose their energy over several collisions give several lower-energy photons of longer wavelength.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0366';
UPDATE questions SET stem = 'A K_{β} X-ray photon is emitted when an electron', why = 'All K-series lines are emitted when an electron fills a vacancy in the K-shell. If the electron comes from the L-shell, the photon is K_{α}. If it comes from the M-shell, the next shell out, the photon is K_{β}, which has more energy because the drop is larger.', wrong = '{"1": "An electron dropping from the L-shell to the K-shell gives the K_{α} line, not K_{β}.", "2": "A transition that ends in the L-shell produces an L-series line. K-lines always end in the K-shell.", "3": "Knocking an electron out of the K-shell only creates the vacancy. The X-ray photon comes from the electron that fills it."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0368';
UPDATE questions SET stem = 'For the same target, how do the K_{α} and K_{β} X-ray photons compare?', options = '["K_{α} has higher energy and shorter wavelength than K_{β}", "K_{β} has higher energy and shorter wavelength than K_{α}", "they have equal energies", "K_{β} has higher energy and longer wavelength than K_{α}"]', why = 'K_{β} comes from an M → K transition and K_{α} from an L → K transition. The M-shell is further from the K-shell, so the energy drop is larger and the K_{β} photon has more energy. Since E = hc/λ, higher energy means a shorter wavelength.', wrong = '{"0": "This reverses the facts. The L → K drop is smaller than M → K, so K_{α} has the lower energy and longer wavelength.", "2": "The L and M shells have different energies, so the two transitions release different amounts of energy.", "3": "K_{β} does have higher energy, but by E = hc/λ a higher energy means a shorter wavelength, not a longer one."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0369';
UPDATE questions SET stem = 'The K_{α} line of a target has a photon energy of 8.0 keV. What is its wavelength? (h = 6.63 × 10⁻³⁴ J s, c = 3 × 10⁸ m s⁻¹, e = 1.6 × 10⁻¹⁹ C)', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0371';
UPDATE questions SET why = 'As X-rays pass through the body, they interact with atoms, ionizing them and transferring energy, so the beam gradually weakens. This loss of intensity is called attenuation. It follows an exponential law, I = I₀e^{−μx}, where μ is the attenuation coefficient and x is the thickness.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0372';
UPDATE questions SET why = 'Attenuation follows I = I₀e^{−μx}. First convert the thickness: x = 2.0 cm = 0.020 m, so μx = 50 m⁻¹ × 0.020 m = 1. Then I ÷ I₀ = e⁻¹ ≈ 0.37, so about 37% of the original intensity gets through.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0373';
UPDATE questions SET why = 'With μ = 0.693 cm⁻¹ = ln 2 per cm, each 1.0 cm of material halves the intensity. To reach one quarter the beam must be halved twice, so 2.0 cm is needed. Using the formula, e^{−μx} = 1/4 gives μx = ln 4 = 1.386, so x = 1.386 ÷ 0.693 = 2.0 cm.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0374';
UPDATE questions SET why = 'When the pair annihilates at rest, its whole rest-mass energy becomes photon energy: 2m_{e}c² ≈ 2 × 0.51 MeV = 1.02 MeV. This is shared equally by the two photons, so each has m_{e}c² ≈ 0.51 MeV, the rest-mass energy of one electron.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0386';
UPDATE questions SET why = 'Equal luminosity means 4πr²σT⁴ is the same for both stars, so r²T⁴ is constant and r is proportional to 1/T². Star X is twice as hot, so r_{X}/r_{Y} = 1/2² = 1/4. A hotter star with the same luminosity must be smaller.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0399';
UPDATE questions SET wrong = '{"0": "Edwin Hubble later used Cepheids to measure the distances of galaxies and found Hubble''s law, but he did not discover their pulsation pattern.", "2": "Wilhelm Wien is known for the displacement law, λ_{max} T = constant, for blackbody radiation.", "3": "Albert Einstein is known for relativity and the photoelectric effect, not for work on Cepheid variable stars."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0405';
UPDATE questions SET wrong = '{"0": "The glow of a hot object is light it emits itself, not light it reflects from its surroundings.", "1": "Thermal radiation depends only on temperature, not on the shape of the object.", "3": "This is reversed. As temperature rises the peak wavelength becomes shorter, by Wien''s law λ_{max} T = constant."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0410';
UPDATE questions SET why = 'Wien''s displacement law is λ_{max} T = b, so T = b ÷ λ_{max}. Converting 725 nm to 725 × 10⁻⁹ m, T = 2.9 × 10⁻³ m K ÷ 7.25 × 10⁻⁷ m = 4000 K. A peak in the red end of the spectrum means a fairly cool star.', wrong = '{"0": "400 K comes from using a wavelength ten times too long, 7250 nm, a slip in converting nanometres to metres.", "1": "40 000 K comes from using a wavelength ten times too short, 72.5 nm, a slip in converting nanometres.", "2": "About 2.1 × 10⁻⁹ comes from multiplying b by λ_{max} instead of dividing."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0411';
UPDATE questions SET why = 'By Wien''s displacement law, λ_{max} = b ÷ T = 2.9 × 10⁻³ m K ÷ 10 000 K = 2.9 × 10⁻⁷ m = 290 nm. This is shorter than violet light (about 400 nm), so it lies in the ultraviolet. Very hot stars therefore look blue-white.', wrong = '{"1": "2.9 μm is ten times too long, a power-of-ten slip. It would be the peak of a star at only 1000 K.", "2": "580 nm is the peak for a star of 5000 K. Doubling T to 10 000 K halves λ_{max} to 290 nm.", "3": "29 nm is ten times too short, a power-of-ten slip. It would be the peak of a star at about 100 000 K."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0412';
UPDATE questions SET why = 'By Wien''s law, λ_{max} = b ÷ T = 2.9 × 10⁻³ m K ÷ 310 K ≈ 9.4 × 10⁻⁶ m = 9.4 μm. This lies in the infrared. That is why the human body does not glow visibly but can be seen by infrared night-vision cameras.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0413';
UPDATE questions SET why = 'By Wien''s law, T is inversely proportional to λ_{max}, so T_{A}/T_{B} = 600 nm ÷ 300 nm = 2. With equal radii, the Stefan–Boltzmann law gives L ∝ T⁴, so L_{A}/L_{B} = 2⁴ = 16. Star A is hotter and therefore far more luminous.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0414';
UPDATE questions SET options = '["Aₓ = A sin θ and A_{y} = A cos θ", "Aₓ = A tan θ and A_{y} = A/tan θ", "Aₓ = A_{y} = A/2", "Aₓ = A cos θ and A_{y} = A sin θ"]', why = 'Draw the vector A at angle θ to the x-axis and drop perpendiculars to the axes, forming a right-angled triangle with A as the hypotenuse. The side along the x-axis is adjacent to θ, so Aₓ = A cos θ. The side along the y-axis is opposite θ, so A_{y} = A sin θ.', wrong = '{"0": "These are swapped. For an angle measured from the x-axis, the x-component is adjacent to θ and uses cos θ.", "1": "Components are found with sine and cosine of the angle, since A is the hypotenuse. Tan gives the ratio A_{y}/Aₓ, not a component.", "2": "The two components are equal only at 45°, and even then each is A cos 45° = A/√2, not A/2."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0507';
UPDATE questions SET why = 'The y-component of a vector at angle θ to the x-axis is F_{y} = F sin θ. Here F_{y} = 20 N × sin 30° = 20 × 0.5 = 10 N. The x-component would be 20 cos 30° ≈ 17.3 N. Check: 10² + 17.3² ≈ 400 = 20², as it should be.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0508';
UPDATE questions SET stem = 'A vector has rectangular components Aₓ = −3 units and A_{y} = 4 units. Its magnitude is:', why = 'The two rectangular components are at right angles, so the magnitude comes from Pythagoras'' theorem: A = √(Aₓ² + A_{y}²) = √((−3)² + 4²) = √(9 + 16) = √25 = 5 units. The negative sign only shows direction; squaring removes it.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0509';
UPDATE questions SET stem = 'A vector has components Aₓ = 5 units and A_{y} = 5√3 units. The angle it makes with the x-axis is:', why = 'The angle with the x-axis is θ = tan⁻¹(A_{y} ÷ Aₓ). Here A_{y} ÷ Aₓ = 5√3 ÷ 5 = √3, and tan 60° = √3, so θ = 60°. Both components are positive, so the vector lies in the first quadrant.', wrong = '{"0": "tan 30° = 1/√3, which would need A_{y} = Aₓ/√3. Here the ratio is √3, giving 60°.", "1": "45° needs the two components to be equal, so that tan θ = 1.", "3": "90° would need Aₓ = 0, with the vector pointing straight along the y-axis."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0510';
UPDATE questions SET why = 'In component form, A·B = AₓBₓ + A_{y}B_{y} + A_{z}B_{z}. Substituting, A·B = (2)(1) + (3)(−1) + (−1)(1) = 2 − 3 − 1 = −2. A negative answer means the angle between the vectors is more than 90°.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0516';
UPDATE questions SET why = 'The three equations of motion, such as v_{f} = v_{i} + at, were derived assuming the acceleration stays constant and the body moves along a straight line. So they can only be applied to objects moving in a straight line with constant acceleration.', wrong = '{"0": "In circular motion the direction keeps changing, so the acceleration is not constant in direction. The straight-line equations do not apply.", "1": "The equations are derived for constant acceleration. If the acceleration varies, they give wrong results.", "2": "The equations include an initial velocity v_{i}, so the body does not need to start from rest."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0523';
UPDATE questions SET why = 'For any velocity–time graph, the area under the line gives the displacement. For uniform acceleration this area is a rectangle of area v_{i} t plus a triangle of area ½(at)t. Adding them gives S = v_{i} t + ½at², the second equation of motion.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0525';
UPDATE questions SET why = 'Use the first equation of motion, v_{f} = v_{i} + at. Substituting, v_{f} = 4 m s⁻¹ + (1.5 m s⁻²)(6 s) = 4 + 9 = 13 m s⁻¹. The 9 m s⁻¹ is the velocity gained, added to the starting velocity.', wrong = '{"0": "9 m s⁻¹ is only the velocity gained, at = 1.5 × 6. The initial 4 m s⁻¹ has been left out.", "1": "11.5 m s⁻¹ comes from adding 4, 1.5 and 6 together. The acceleration must be multiplied by the time.", "3": "31 m s⁻¹ comes from 4 + ½ × 1.5 × 6² = 4 + 27, mixing in the distance formula instead of v_{f} = v_{i} + at."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0526';
UPDATE questions SET why = 'Use the second equation of motion, S = v_{i} t + ½at². Substituting, S = (12)(4) + ½(3)(4²) = 48 + ½ × 3 × 16 = 48 + 24 = 72 m. The first term is the distance at constant speed, and the second is the extra distance due to acceleration.', wrong = '{"0": "24 m is only ½at², the extra distance due to acceleration. The 48 m from the initial speed is missing.", "1": "48 m is only v_{i} t, as if the car kept a constant speed. The ½at² term is missing.", "3": "96 m uses at² = 3 × 16 = 48 instead of ½at² = 24 for the second term."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0527';
UPDATE questions SET why = 'Time is not given, so use the third equation, v_{f}² − v_{i}² = 2aS. Starting from rest, v_{i} = 0, so 30² − 0 = 2a(150). This gives 900 = 300a, so a = 3 m s⁻². A check: reaching 30 m s⁻¹ at 3 m s⁻² takes 10 s, and the average speed of 15 m s⁻¹ over 10 s gives 150 m.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0528';
UPDATE questions SET why = 'Use v_{f}² − v_{i}² = 2aS with v_{f} = 0, v_{i} = 20 m s⁻¹ and a = −0.5 m s⁻², negative because it opposes the motion. Then 0 − 400 = 2(−0.5)S, so −400 = −S and S = 400 m. A check: it takes 20 ÷ 0.5 = 40 s to stop, at an average speed of 10 m s⁻¹, which also gives 400 m.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0529';
UPDATE questions SET why = 'For a body dropped from rest, v_{i} = 0, so h = v_{i} t + ½gt² = ½gt². Substituting, h = ½ × 9.8 × (2.0)² = ½ × 9.8 × 4 = 19.6 m. Because h depends on t², doubling the fall time makes the height four times larger.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0532';
UPDATE questions SET why = 'At the highest point the ball stops for an instant, so v_{f} = 0. Taking upward as positive, a = −g, so v_{f} = v_{i} − gt gives 0 = 14.7 − 9.8t. Hence t = 14.7 ÷ 9.8 = 1.5 s. The ball loses 9.8 m s⁻¹ of upward speed every second until none is left.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0533';
UPDATE questions SET why = 'At the top v_{f} = 0. Using v_{f}² − v_{i}² = −2gh, 0 − (19.6)² = −2(9.8)h. So h = 384.16 ÷ 19.6 = 19.6 m. A quick check: the ball takes 19.6 ÷ 9.8 = 2 s to reach the top, at an average speed of 9.8 m s⁻¹, and 9.8 × 2 = 19.6 m.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0534';
UPDATE questions SET why = 'The initial vertical component of velocity is v_{i} sin θ. Taking upward as positive, the vertical acceleration is −g. Using v_{f} = v_{i} + at for the vertical motion, v_{y} = v_{i} sin θ − gt.', wrong = '{"1": "v_{i} cos θ is the horizontal component, which stays constant. It is not part of the vertical velocity.", "2": "Gravity acts downward and reduces the upward velocity, so gt is subtracted, not added.", "3": "v_{i} sin θ is only the initial vertical component. It changes with time because of gravity."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0538';
UPDATE questions SET why = 'At the highest point the vertical component of velocity has fallen to zero, v_{y} = 0. The horizontal component does not change during the flight, so it is still v_{i} cos θ. The projectile''s velocity at the top is therefore horizontal and equal to v_{i} cos θ.', wrong = '{"1": "Only the vertical component is zero at the top. The horizontal component v_{i} cos θ remains, so the velocity is not zero.", "2": "The acceleration is g downward at every point of the flight, including the highest point.", "3": "The speed is smallest at the top, because the vertical component is zero there. It is greatest at launch and landing."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0539';
UPDATE questions SET why = 'At maximum height the vertical velocity is zero. For the vertical motion, use 2aS = v_{f}² − v_{i}² with a = −g, v_{f} = 0 and v_{i} = v_{i} sin θ. This gives −2gh = −v_{i}² sin²θ, so h = v_{i}² sin²θ ÷ 2g.', wrong = '{"0": "v_{i}² sin 2θ / g is the horizontal range, not the maximum height.", "2": "2v_{i} sin θ / g is the time of flight, not a height. Its unit is seconds.", "3": "v_{i}² / 2g is the maximum height only for a vertical launch, θ = 90°, where sin θ = 1."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0540';
UPDATE questions SET why = 'The time of flight on level ground is T = 2v_{i} sin θ ÷ g. Substituting, T = 2 × 20 × sin 30° ÷ 10 = 2 × 20 × 0.5 ÷ 10 = 2 s. The ball takes 1 s to rise to its highest point and another 1 s to fall back to the ground.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0541';
UPDATE questions SET why = 'The range on level ground is R = v_{i}² sin 2θ ÷ g. Here 2θ = 30°, so R = (40)² × sin 30° ÷ 10 = 1600 × 0.5 ÷ 10 = 80 m. A common slip is to use sin θ instead of sin 2θ, so the angle must be doubled before taking the sine.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0542';
UPDATE questions SET why = 'The range is R = v_{i}² sin 2θ ÷ g, so it depends on sin 2θ. Since sin 2θ = sin(180° − 2θ), the angles θ and 90° − θ give the same range. With θ = 25°, the other angle is 90° − 25° = 65°. Check: sin 50° = sin 130°.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0543';
UPDATE questions SET why = 'Set the maximum height equal to the range: v_{i}² sin²θ ÷ 2g = v_{i}² sin 2θ ÷ g = 2v_{i}² sin θ cos θ ÷ g. Cancelling v_{i}² sin θ ÷ g gives sin θ ÷ 2 = 2 cos θ, so sin θ = 4 cos θ and tan θ = 4, which is about 76°.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0544';
UPDATE questions SET why = 'Newton''s second law can be written as F = (mv_{f} − mv_{i}) ÷ t, force equals the rate of change of momentum. This form does not assume the mass is fixed. So it can describe bodies whose mass changes as they move, such as a rocket that loses mass as it burns its fuel.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0548';
UPDATE questions SET why = 'Force equals the rate of change of momentum: F = (mv_{f} − mv_{i}) ÷ t = 1200 × (10 − 25) ÷ 4.0 = 1200 × (−15) ÷ 4.0 = −4500 N. The size of the force is 4500 N, and the minus sign shows it acts against the motion.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0550';
UPDATE questions SET why = 'Tangential acceleration is linked to angular acceleration by a_{t} = rα, just as v = rω. Here a_{t} = 0.25 m × 4 rad s⁻² = 1 m s⁻². Points farther from the axis would have a larger tangential acceleration.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0579';
UPDATE questions SET wrong = '{"0": "Linear speed v = rω grows with distance from the axis, so points farther out move faster.", "1": "Tangential acceleration a_{t} = rα also depends on r, so it differs from point to point.", "3": "Distance travelled along the path, S = rθ, is larger for points farther from the axis."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0580';
UPDATE questions SET why = 'Use the angular form of S = v_{i} t + ½at²: θ = ω_{i} t + ½αt². Starting from rest, ω_{i} = 0, so θ = ½ × 2 × 5² = ½ × 2 × 25 = 25 rad. This is the rotational version of the distance travelled from rest, S = ½at².', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0582';
UPDATE questions SET why = 'The angular acceleration is α = (0 − 4.0) ÷ 10 = −0.4 rev s⁻². Then θ = ω_{i} t + ½αt² = 4.0 × 10 − ½ × 0.4 × 100 = 40 − 20 = 20 rev. A quick check: the average angular speed is (4.0 + 0) ÷ 2 = 2 rev s⁻¹, and 2 × 10 = 20 rev.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0583';
UPDATE questions SET stem = 'Which angular equation corresponds to the linear equation 2aS = v_{f}² − v_{i}²?', options = '["2αθ = ω_{f}² − ω_{i}²", "θ = ω_{i} t + ½αt²", "ω_{f} = ω_{i} + αt", "τ = Iα"]', why = 'Each angular equation is obtained from a linear one by replacing S with θ, v with ω and a with α. So 2aS = v_{f}² − v_{i}² becomes 2αθ = ω_{f}² − ω_{i}². Like its linear partner, it is used when the time is not given.', wrong = '{"1": "θ = ω_{i} t + ½αt² is the angular form of S = v_{i} t + ½at², the second equation of motion.", "2": "ω_{f} = ω_{i} + αt is the angular form of v_{f} = v_{i} + at, the first equation of motion.", "3": "τ = Iα is the rotational form of Newton''s second law, F = ma, not an equation of angular motion."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0584';
UPDATE questions SET stem = 'Satellite X orbits at radius r and satellite Y at radius 4r around the same planet. The ratio of their orbital speeds vₓ : v_{Y} is:', why = 'Orbital speed is v = √(GM/r), so v is proportional to 1/√r. Then vₓ ÷ v_{Y} = √(r_{Y} ÷ r_{X}) = √(4r ÷ r) = √4 = 2. So the inner satellite moves twice as fast, and the ratio is 2 : 1.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0603';
UPDATE questions SET why = 'To escape, the initial kinetic energy must equal the increase in potential energy from the surface to infinity: ½mv² = GMm/R. The mass m cancels, so v² = 2GM/R and v_{esc} = √(2GM/R). Using GM = gR², this is also √(2gR).', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0654';
UPDATE questions SET why = 'Using v_{esc} = √(2gR) with g = 9.8 m s⁻² and R = 6.4 × 10⁶ m gives √(1.25 × 10⁸) ≈ 1.1 × 10⁴ m s⁻¹. That is about 11 km s⁻¹, the Earth''s escape velocity.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0655';
UPDATE questions SET options = '["v_{esc} = 2v_{orbit} because the satellite must go round twice", "Escape velocity depends on the mass of the body, orbital speed does not", "v_{esc} = √(2GM/R) while v_{orbit} = √(GM/R)", "Orbital speed includes the Earth''s rotation"]', why = 'The escape velocity is v_{esc} = √(2GM/R), while a satellite skimming the surface needs v_{orbit} = √(GM/R). Dividing gives v_{esc}/v_{orbit} = √2. Check: 7.9 km s⁻¹ × 1.41 ≈ 11.2 km s⁻¹.', wrong = '{"0": "The ratio is √2, about 1.41, not 2. It comes from the factor 2 inside the square root.", "1": "Neither speed depends on the mass of the moving body. In both formulas the body''s mass cancels.", "3": "The formulas v_{esc} = √(2GM/R) and v_{orbit} = √(GM/R) contain no term for the Earth''s rotation."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0656';
UPDATE questions SET why = 'For escape, ½mv² = GMm/R. The rocket''s mass m appears on both sides and cancels, leaving v_{esc} = √(2GM/R). So escape velocity depends only on the planet''s mass M and radius R. A heavier rocket needs more energy to escape, but not more speed.', wrong = '{"0": "A heavier rocket needs more kinetic energy, but its required speed is the same. The mass cancels from ½mv² = GMm/R.", "1": "The rocket''s mass does not appear in v_{esc} = √(2GM/R), so a lighter rocket needs the same speed.", "2": "Escape velocity is defined from energy, which does not depend on direction. The launch angle does not bring the rocket''s mass into it."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0657';
UPDATE questions SET why = 'The work–energy theorem says the work done on a body by the net force equals the change in its kinetic energy: W = ½mv_{f}² − ½mv_{i}². It follows from F = ma combined with the equation 2ad = v_{f}² − v_{i}².', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0658';
UPDATE questions SET stem = 'Which of these materials has the largest Young''s modulus?', why = 'Young''s modulus measures stiffness: how much stress is needed for a given strain. Diamond has by far the largest value, about 1120 × 10⁹ N m⁻², because its carbon atoms are held by very strong bonds in a rigid network.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0682';
UPDATE questions SET why = 'Upthrust = weight of air displaced = ρ_{air} gV = 1.25 × 10 × 8 = 100 N. The balloon itself, fabric and helium together, weighs 50 N. The largest extra load is the upthrust minus the balloon''s weight: 100 N − 50 N = 50 N.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0698';
UPDATE questions SET stem = 'For a small sphere falling through a fluid, the terminal velocity v_{t} = 2gr²ρ/9η. If the radius of the drop is doubled, the terminal velocity becomes:', why = 'The terminal velocity formula v_{t} = 2gr²ρ/9η shows that v_{t} is proportional to r². Doubling the radius multiplies r² by 2² = 4, so the terminal velocity becomes four times as large. This is why big raindrops fall faster than fine drizzle.', wrong = '{"0": "This treats v_{t} as proportional to r. The formula has r², so doubling r gives four times the speed.", "1": "Larger drops fall faster, not slower. Their weight grows as r³ while the drag grows only as r.", "3": "Eight times would need v_{t} ∝ r³. The weight grows as r³, but the drag grows as r, so v_{t} goes as r²."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0719';
UPDATE questions SET why = 'v_{t} = 2gr²ρ/9η. With r² = (2.0 × 10⁻⁵)² = 4.0 × 10⁻¹⁰ m², the top line is 2 × 9.8 × 4.0 × 10⁻¹⁰ × 1000 = 7.84 × 10⁻⁶ and the bottom line is 9 × 2.0 × 10⁻⁵ = 1.8 × 10⁻⁴. So v_{t} = 7.84 × 10⁻⁶ ÷ 1.8 × 10⁻⁴ ≈ 0.044 m s⁻¹.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0720';
UPDATE questions SET why = 'According to the kinetic theory, the average kinetic energy of gas molecules is directly proportional to the absolute (kelvin) temperature: ⟨KE⟩ = (3/2)k_{B}T. Doubling the kelvin temperature doubles the average kinetic energy.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0726';
UPDATE questions SET wrong = '{"0": "The number of molecules is N, used in the form PV = Nk_{B}T. In PV = nRT the quantity n counts moles.", "1": "Density is mass per unit volume, ρ = PM/RT. It is not a symbol in PV = nRT.", "2": "Molar mass is M, which links mass to moles through n = m/M. It is not n itself."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0728';
UPDATE questions SET stem = 'The Boltzmann constant k_{B} is related to the gas constant R and Avogadro''s number N_{A} by:', options = '["k_{B} = R/N_{A}", "k_{B} = R × N_{A}", "k_{B} = N_{A}/R", "k_{B} = R/T"]', why = 'The Boltzmann constant is the gas constant for a single molecule. Dividing the gas constant R (per mole) by Avogadro''s number N_{A} (molecules per mole) gives k_{B} = R/N_{A} = 8.31 ÷ 6.02 × 10²³ ≈ 1.38 × 10⁻²³ J K⁻¹.', wrong = '{"1": "R × N_{A} would be about 5 × 10²⁴, a huge number. k_{B} is a tiny constant because it applies to a single molecule.", "2": "N_{A}/R is the inverse of the correct relation and has the wrong units.", "3": "R/T changes with temperature, so it cannot be a constant like k_{B}."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0729';
UPDATE questions SET options = '["PV = NRT", "PV = Nk_{B}T", "PV = nk_{B}T", "P = Nk_{B}TV"]', why = 'The number of moles is n = N/N_{A}, and the gas constant is R = N_{A} k_{B}. Substituting into PV = nRT gives PV = (N/N_{A})(N_{A} k_{B})T = Nk_{B}T. This is the ideal gas equation written for N molecules.', wrong = '{"0": "R goes with the number of moles. When N counts molecules, the matching constant is k_{B}.", "2": "When n counts moles, the matching constant is R. Mixing n with k_{B} gives a value N_{A} times too small.", "3": "Volume multiplies the pressure on the left side. P = Nk_{B}TV would make pressure grow with volume, which is wrong."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0730';
UPDATE questions SET stem = 'The average translational kinetic energy of a gas molecule at 300 K is (k_{B} = 1.38 × 10⁻²³ J K⁻¹):', why = 'The kinetic theory gives the average translational kinetic energy of one molecule as ⟨KE⟩ = (3/2)k_{B}T. At 300 K: ⟨KE⟩ = 1.5 × 1.38 × 10⁻²³ J K⁻¹ × 300 K ≈ 6.2 × 10⁻²¹ J.', wrong = '{"0": "1.2 × 10⁻²⁰ J is 3k_{B}T, twice the correct value. The factor is 3/2, not 3.", "1": "3.7 × 10³ J is (3/2)RT, which uses R. That is the energy of a whole mole, not of one molecule.", "2": "4.1 × 10⁻²¹ J is k_{B}T alone. The factor 3/2 is missing."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0742';
UPDATE questions SET options = '["PV = constant", "P/V = constant", "PVᵞ = constant, where γ = C_{p}/C_{v}", "V/T = constant"]', why = 'In an adiabatic change the temperature does not stay constant, so Boyle''s law does not apply. Instead an ideal gas follows PVᵞ = constant, where γ = C_{p}/C_{v} is the ratio of the molar specific heat at constant pressure to that at constant volume.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0754';
UPDATE questions SET wrong = '{"0": "PV is constant on an isotherm. On an adiabat PVᵞ is constant.", "1": "No heat is exchanged in an adiabatic change. The temperature rises because of the work done on the gas.", "2": "γ = C_{p}/C_{v} is always greater than 1, since C_{p} is larger than C_{v}. That is why the adiabat is steeper."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0755';
UPDATE questions SET why = 'A moving source squeezes the waves in front of it, so the wavelength becomes (v − u_{s})/f and the frequency heard rises. But once a sound wave leaves the source, its speed depends only on the air. In still air the speed of sound v stays the same.', wrong = '{"1": "The wavelength in front of an approaching source is shortened to (v − u_{s})/f, so it does change.", "2": "The listener hears a higher apparent frequency as the source approaches, so the frequency changes.", "3": "Both the wavelength and the frequency change. Only the speed of sound in still air stays the same."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0824';
UPDATE questions SET why = 'For a source moving towards a stationary observer, f′ = vf/(v − u_{s}). Here f′ = 340 × 680 ÷ (340 − 20) = 231 200 ÷ 320 = 722.5 Hz, about 723 Hz. The pitch heard is higher because the siren is approaching.', wrong = '{"0": "642 Hz uses v + u_{s} in the bottom line, the formula for a source moving away. This siren is approaching.", "1": "680 Hz is the siren''s true frequency. A moving source changes the frequency heard.", "2": "700 Hz adds the source speed to the frequency (680 + 20). A speed cannot be added to a frequency."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0825';
UPDATE questions SET why = 'For a source moving away from a stationary observer, the waves are stretched and f′ = vf/(v + u_{s}). Here f′ = 360 × 500 ÷ (360 + 40) = 180 000 ÷ 400 = 450 Hz, lower than the true 500 Hz.', wrong = '{"0": "444 Hz is f(1 − u_{s}/v), the formula for a moving observer, not a moving source. A moving source uses vf/(v + u_{s}).", "2": "500 Hz is the whistle''s true frequency. A receding source is heard at a lower frequency.", "3": "563 Hz uses v − u_{s}, the formula for an approaching source. This train is moving away."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0826';
UPDATE questions SET why = 'For an approaching source, f′/f = v/(v − u_{s}). Setting this equal to 1.25 gives v − u_{s} = v ÷ 1.25 = 0.8v. So u_{s} = 0.2v = 0.2 × 340 = 68 m s⁻¹. Check: 340 ÷ (340 − 68) = 340 ÷ 272 = 1.25.', wrong = '{"1": "85 m s⁻¹ is 0.25 × 340, which assumes the frequency rises by the same fraction as the source speed. Solving v/(v − u_{s}) = 1.25 gives 0.2v.", "2": "272 m s⁻¹ is v − u_{s} = 0.8 × 340. The source speed is the difference, 340 − 272 = 68 m s⁻¹.", "3": "425 m s⁻¹ is 1.25 × 340, faster than sound. A source that fast would not fit this formula at all."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0827';
UPDATE questions SET stem = 'A source emits sound of frequency f and moves towards a stationary listener at speed u_{s}; the speed of sound is v. The wavelength reaching the listener is:', options = '["(v − u_{s})/f", "(v + u_{s})/f", "v/f", "vf/(v − u_{s})"]', why = 'In one period, 1/f, the sound travels v/f, while the source moves u_{s}/f towards the listener. So each wave is squeezed into a shorter distance: λ′ = v/f − u_{s}/f = (v − u_{s})/f.', wrong = '{"1": "(v + u_{s})/f is the longer wavelength behind the source, heard by a listener the source is moving away from.", "2": "v/f is the wavelength when the source is at rest. Motion towards the listener shortens it.", "3": "vf/(v − u_{s}) is the apparent frequency heard by the listener, not the wavelength."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0828';
UPDATE questions SET why = 'A dielectric medium between two charges reduces the force between them by a factor equal to its relative permittivity εr: F_{medium} = F_{air}/εr. Air has εr very close to 1, so F_{medium} = 0.8 N ÷ 4 = 0.2 N.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0881';
UPDATE questions SET stem = 'Which of these materials has a relative permittivity closest to 1?', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0885';
UPDATE questions SET stem = '6 J of work is done in moving a charge of +2 C from point A to point B while keeping it in equilibrium. The potential difference V_{B} − V_{A} is:', why = 'The potential difference between two points is the work done per unit charge in moving a positive charge from one point to the other, keeping it in equilibrium: ΔV = W/q. Here V_{B} − V_{A} = 6 J ÷ 2 C = 3 V, since 1 J C⁻¹ = 1 V.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0901';
UPDATE questions SET stem = 'Wire A is twice as long as wire B and has twice its diameter; both are of the same metal. The ratio R_{A} : R_{B} is:', why = 'R = ρL/A, and the area of a round wire is proportional to the square of its diameter. Wire A has twice the length and, with twice the diameter, four times the area. So R_{A}/R_{B} = (2/4) ÷ 1 = 1/2, giving R_{A} : R_{B} = 1 : 2.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0917';
UPDATE questions SET why = 'Resistance varies with temperature as R_{t} = R₀(1 + αt). Here R_{t} = 50 Ω × (1 + 0.004 × 100) = 50 × 1.4 = 70 Ω. The resistance rises by R₀αt = 50 × 0.4 = 20 Ω, a 40% increase over the 100 K rise.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0921';
UPDATE questions SET why = 'The temperature coefficient is the fractional change in resistance per kelvin: α = (R_{t} − R₀)/(R₀t). Here α = (46 − 40) ÷ (40 × 50) = 6 ÷ 2000 = 3.0 × 10⁻³ K⁻¹.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0922';
UPDATE questions SET stem = 'The resistance of which material changes least with temperature?', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0924';
UPDATE questions SET why = 'With a steady current, the potential drop along a uniform potentiometer wire is proportional to length. So the emf balanced at length ℓ is E_{x} = E × ℓ/L = 2.0 × 75/100 = 1.5 V.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0936';
UPDATE questions SET stem = 'Which isotope is a typical source of gamma rays?', why = 'Cobalt-60 is the standard gamma source, used for example in radiotherapy and to sterilize medical equipment. Radon-222 is a typical alpha source and strontium-90 a typical beta source.', wrong = '{"0": "Radon-222 is a typical alpha source, not a gamma source.", "2": "Uranium-238 is an alpha emitter and is not used as a gamma source.", "3": "Carbon-12 is a stable isotope and emits no radiation at all."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1036';
UPDATE questions SET wrong = '{"0": "⅓ goes with m<v²>, not with ½m<v²>. Rewriting in terms of kinetic energy doubles the factor to ⅔.", "1": "3/2 is the factor in <K.E.> = (3/2)k_{B}T, not in the pressure formula.", "3": "P = n<K.E.> leaves out the factor ⅔, which comes from averaging motion over three directions and from K.E. = ½mv²."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1502';
UPDATE questions SET stem = 'How many moles of gas are there in 3.01 × 10²³ molecules? (N_{A} = 6.02 × 10²³ mol⁻¹)', why = 'One mole contains Avogadro''s number of molecules, N_{A} = 6.02 × 10²³. So the number of moles is n = N/N_{A} = 3.01 × 10²³ ÷ 6.02 × 10²³ = 0.50 mol. A quick check: 3.01 is exactly half of 6.02.', wrong = '{"0": "2.0 mol comes from the inverted ratio, N_{A} ÷ N. 2.0 mol would contain 1.204 × 10²⁴ molecules.", "1": "1.81 × 10⁴⁷ mol comes from multiplying N by N_{A} instead of dividing.", "2": "0.25 mol would contain only 1.505 × 10²³ molecules, half the number given."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1506';
UPDATE questions SET why = 'The average translational kinetic energy of a gas molecule is <K.E.> = (3/2)k_{B}T, so it is directly proportional to the absolute temperature. Halving T therefore halves the average kinetic energy.', wrong = '{"0": "A fourfold fall would need the absolute temperature to drop to a quarter, not to half.", "2": "The kinetic energy depends directly on temperature, so it must change when T changes.", "3": "A fall by √2 describes how the rms speed changes when T is halved, since v_{rms} ∝ √T. The kinetic energy itself halves."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1507';
UPDATE questions SET why = 'Each molecule has average kinetic energy (3/2)k_{B}T, and one mole has N_{A} molecules. Since N_{A}k_{B} = R, the total is (3/2)RT = 1.5 × 8.31 × 300 ≈ 3.7 × 10³ J, about 3.7 kJ.', wrong = '{"0": "2.5 kJ is RT = 8.31 × 300 ≈ 2.49 kJ. The factor 3/2 is missing.", "1": "1.2 kJ is ½RT, the energy linked with motion along one direction only.", "3": "6.2 × 10⁻²¹ J is (3/2)k_{B}T, the kinetic energy of a single molecule, not of a whole mole."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1508';
UPDATE questions SET why = 'The capacitance of an isolated sphere is C = 4πε₀ε_{r}R. Surrounding it with a medium of dielectric constant ε_{r} multiplies its capacitance by ε_{r}. So the new capacitance is 10 pF × 2.5 = 25 pF.', wrong = '{"0": "4 pF comes from dividing by 2.5. A dielectric increases capacitance, it does not reduce it.", "1": "The surrounding medium does change the capacitance, through the factor ε_{r}.", "2": "12.5 pF comes from adding 2.5 pF instead of multiplying by 2.5."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1561';
UPDATE questions SET why = 'For two capacitors in series, C_{eq} = C₁C₂/(C₁ + C₂) = (3 × 6)/(3 + 6) = 2 μF. The energy stored is ½C_{eq}V² = ½ × 2 × 10⁻⁶ × 90² = 10⁻⁶ × 8100 = 8.1 × 10⁻³ J.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1567';
UPDATE questions SET why = 'The time constant is τ = RC = 2000 × 50 × 10⁻⁶ = 0.10 s, so 0.10 s is exactly one time constant. During discharge V = V₀e^{−t/RC}, so after one time constant V = 20 ÷ 2.718 ≈ 7.4 V, about 37% of the starting voltage.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1569';
UPDATE questions SET why = 'During discharge Q = Q₀e^{−t/RC}. The current, and so the rate at which charge falls, depends on how much charge is left. So the graph falls steeply at first and then flattens out more and more, like water draining from a tank.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1570';
UPDATE questions SET why = 'During discharge the charge falls as Q = Q₀e^{−t/RC}. Since V = Q/C and I = V/R, the voltage and the current are proportional to the charge. So all three decay exponentially, falling by the same factor in the same time, with the same time constant RC.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1571';
UPDATE questions SET wrong = '{"0": "A choke has a very large inductance, made larger by its iron core, not an inductance near zero.", "2": "A choke is a copper coil on an iron core. It is not a semiconductor device.", "3": "With DC, X_{L} = 0 and a choke acts as a small resistance. It is used in AC circuits."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1580';
UPDATE questions SET why = 'Impedance is Z = V_{rms}/I_{rms}. Each rms value is the peak value divided by √2, so the √2 cancels and the ratio of peak values gives the same answer. Z = 200 V ÷ 10 A = 20 Ω.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1584';
UPDATE questions SET options = '["an RC series circuit, because X_{C} is much larger than X_{L}", "an RL series circuit, because X_{L} is much larger than X_{C}", "a pure resistor, because X_{L} = X_{C}", "an open circuit with zero impedance"]', why = 'The reactances are X_{C} = 1/(ωC) and X_{L} = ωL. At low frequency X_{C} is large and X_{L} is small. Well below resonance the capacitive reactance dominates, so the circuit behaves mainly like an RC series circuit, with the current leading the voltage.', wrong = '{"1": "X_{L} dominates at high frequency, above resonance. Below resonance X_{C} is the larger one.", "2": "X_{L} equals X_{C} only at the resonant frequency, where the circuit acts like a pure resistor.", "3": "An open circuit has infinite impedance, not zero, and neither describes this circuit."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1586';
UPDATE questions SET stem = 'In an RLC series circuit the rms voltages are V_{R} = 32 V, V_{L} = 40 V and V_{C} = 16 V. What is the phase angle between the source voltage and the current?', why = 'The phase angle is given by tan θ = (V_{L} − V_{C})/V_{R} = (40 − 16) ÷ 32 = 24 ÷ 32 = 0.75, so θ ≈ 37°. Since V_{L} is larger than V_{C}, the circuit is inductive and the voltage leads the current. The source voltage is √(32² + 24²) = 40 V.', wrong = '{"0": "53° is tan⁻¹(32/24), the complementary angle. Also, in an inductive circuit the current lags, it does not lead.", "1": "A 90° phase angle would need V_{R} = 0, a circuit with no resistance.", "3": "The phase angle is zero only at resonance, when V_{L} = V_{C}. Here 40 V is not equal to 16 V."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1587';
UPDATE questions SET wrong = '{"0": "Increasing R adds damping. Damping could only be removed by reducing R towards zero.", "2": "The resonant frequency is f₀ = 1/(2π√LC). It depends on L and C, not on R.", "3": "The circuit resonates only at the one frequency where X_{L} = X_{C}, whatever the resistance."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1588';
UPDATE questions SET options = '["The source current is maximum and the branch currents are zero.", "All currents are equal to each other.", "The branch currents I_{L} and I_{C} can each be larger than the small source current.", "The current flows only through the resistor and the inductor."]', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1589';
UPDATE questions SET why = 'At resonance X_{L} = X_{C}, so the effects of the inductor and capacitor cancel and the circuit behaves as purely resistive. The voltage and current are then in phase, θ = 0, and the power factor is cos 0° = 1.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1590';
UPDATE questions SET why = 'The opposition of an inductor to AC is its inductive reactance, X_{L} = 2πfL. Rearranging, L = X_{L} ÷ (2πf). Here 2πf = 2 × 3.14 × 50 = 314 s⁻¹, so L = 160 ÷ 314 ≈ 0.51 H.', wrong = '{"0": "3.2 H comes from 160 ÷ 50, which leaves out the factor 2π.", "1": "8000 H comes from multiplying X_{L} by f instead of dividing.", "3": "With 0.05 H the reactance at 50 Hz would be 2π × 50 × 0.05 ≈ 15.7 Ω, only a tenth of 160 Ω."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1593';
UPDATE questions SET why = 'Mutual inductance is M = ε_{s} ÷ (ΔI_{p}/Δt), the emf induced in the secondary per unit rate of change of current in the primary. So M = 1 henry when a primary current changing at 1 A s⁻¹ induces an emf of 1 V in the secondary. The unit is named after Joseph Henry.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1595';
UPDATE questions SET stem = 'Using 1/λ = R_{H}(1/2² − 1/n²) with R_{H} = 1.097 × 10⁷ m⁻¹, what is the wavelength of the first (longest) line of the Balmer series (n = 3)?', why = 'For n = 3, 1/λ = R_{H}(1/4 − 1/9) = R_{H} × 5/36 = 1.097 × 10⁷ × 0.1389 ≈ 1.524 × 10⁶ m⁻¹. Taking the reciprocal gives λ ≈ 6.56 × 10⁻⁷ m, about 656 nm, the red line of hydrogen.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1608';
UPDATE questions SET stem = 'The energy levels of hydrogen are E₁ = −21.8 × 10⁻¹⁹ J and E₂ = −5.45 × 10⁻¹⁹ J. What is the wavelength of the photon emitted in the transition from n = 2 to n = 1? (hc = 1.99 × 10⁻²⁵ J m)', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1609';
UPDATE questions SET stem = 'Americium-241 has a molar mass of 241 g mol⁻¹. How many nuclei are there in a 2.41 μg sample? (N_{A} = 6.02 × 10²³ mol⁻¹)', why = 'First find the number of moles: 2.41 μg = 2.41 × 10⁻⁶ g, and 2.41 × 10⁻⁶ ÷ 241 = 1.0 × 10⁻⁸ mol. Then N = moles × N_{A} = 1.0 × 10⁻⁸ × 6.02 × 10²³ = 6.02 × 10¹⁵ nuclei.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1628';
UPDATE questions SET why = 'In a perfectly elastic collision the relative speed of approach equals the relative speed of separation. A approaches B at 5 m s⁻¹, so afterwards v_{B} − v_{A} = 5. With v_{B} = 4 m s⁻¹, v_{A} = 4 − 5 = −1 m s⁻¹, so A moves backward at 1 m s⁻¹.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-6015';
UPDATE questions SET stem = 'Which statement about what affects the rate of radioactive decay is correct?', updated_at = unixepoch() * 1000 WHERE id = 'PHY-6073';
UPDATE questions SET why = 'Conserve momentum in each direction. pₓ = 2 × 3 = 6 kg m s⁻¹ and p_{y} = 1 × 6 = 6 kg m s⁻¹, so the total momentum is √(6² + 6²) = √72 ≈ 8.49 kg m s⁻¹. The combined mass is 3 kg, so v = 8.49/3 ≈ 2.8 m s⁻¹, at 45° to the x-axis.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-6076';
UPDATE questions SET why = 'The area of a parallelogram with adjacent sides A and B is |A × B|. For vectors in the xy-plane, |A × B| = |AₓB_{y} − A_{y}Bₓ| = |3 × 5 − 4 × (−2)| = 15 + 8 = 23 square units.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7108';
UPDATE questions SET why = 'At the top, the minimum speed is when the tension just becomes zero and gravity alone gives the centripetal force: v_{t}² = gr. From bottom to top the stone rises 2r, so v_{b}² = v_{t}² + 4gr = 5gr = 5 × 10 × 0.9 = 45. Thus v_{b} = √45 ≈ 6.7 m s⁻¹.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7153';
UPDATE questions SET why = 'At the bottom, T_{b} − mg = mv_{b}²/r. At the top, T_{t} + mg = mv_{t}²/r. Energy conservation over the height 2r gives v_{b}² − v_{t}² = 4gr. Subtracting: T_{b} − T_{t} = 2mg + m(4gr)/r = 6mg, whatever the speed.', wrong = '{"0": "2mg counts only the weight terms and forgets that the stone is faster at the bottom.", "2": "4mg counts only the speed difference and forgets the two weight terms.", "3": "5mg mixes this up with v_{b}² = 5gr, the minimum speed condition at the bottom."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7154';
UPDATE questions SET why = 'For an open pipe of length 0.60 m, the fundamental is v/2L = v/1.2 and the first overtone (2nd harmonic) is twice this, v/0.60. A closed pipe''s fundamental is v/4L_{c}. Setting v/4L_{c} = v/0.60 gives 4L_{c} = 0.60 m, so L_{c} = 0.15 m = 15 cm.', wrong = '{"1": "30 cm would match the open pipe''s fundamental (v/1.2), not its first overtone.", "2": "7.5 cm comes from using v/8L_{c} for the closed pipe''s fundamental instead of v/4L_{c}.", "3": "60 cm makes the two pipes the same length. A closed pipe has a lower fundamental than an open pipe of equal length."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7177';
UPDATE questions SET why = 'When the source moves away from a stationary observer, the waves are stretched out and the frequency falls. f′ = f × v/(v + v_{s}) = 600 × 340/(340 + 34) = 600 × 340/374 ≈ 545 Hz.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7183';
UPDATE questions SET why = 'Case 1, moving source: f′ = f × v/(v − v_{s}) = 600 × 340/306 ≈ 667 Hz. Case 2, moving listener: f′ = f × (v + v₀)/v = 600 × 374/340 = 660 Hz. The results differ because the Doppler shift depends on which one moves through the air, not just their relative speed.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7184';
UPDATE questions SET why = 'Approaching, the observer hears f × v/(v − v_{s}) = 500 × 340/320 ≈ 531.3 Hz. Moving away, the observer hears f × v/(v + v_{s}) = 500 × 340/360 ≈ 472.2 Hz. The drop as the train passes is 531.3 − 472.2 ≈ 59 Hz.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7185';
UPDATE questions SET why = 'For a source moving towards a stationary listener, f′/f = v/(v − v_{s}). A frequency 10% higher means f′/f = 1.1. So 330 = 1.1(330 − v_{s}), giving 330 − v_{s} = 300 and v_{s} = 30 m s⁻¹.', wrong = '{"0": "33 m s⁻¹ is 10% of the speed of sound. That is the speed a moving listener would need, not a moving source.", "2": "36 m s⁻¹ does not come from the Doppler formula. It would give a rise of more than 10%.", "3": "300 m s⁻¹ is v − v_{s}, an intermediate step. The source speed is 330 − 300 = 30 m s⁻¹."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7186';
UPDATE questions SET stem = 'A uniform electric field of 2000 V m⁻¹ points in the +x direction. Point B is 3 cm further along +x than point A. The potential difference V_{A} − V_{B} is', why = 'Potential falls along the direction of the electric field. In a uniform field the potential difference is ΔV = Ed = 2000 × 0.03 = 60 V. B is further along the field, so B is lower and V_{A} − V_{B} = +60 V.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7220';
UPDATE questions SET why = 'The time constant is τ = RC = 2 × 10⁶ Ω × 5 × 10⁻⁶ F = 10 s. During discharge the voltage falls as V = V₀e^{−t/τ}. It reaches half when e^{−t/τ} = ½, so t = τ ln 2 = 10 × 0.693 ≈ 6.9 s.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7227';
UPDATE questions SET why = 'While a capacitor charges, the current dies away exponentially: I = I₀e^{−t/RC}. At t = 2RC, I/I₀ = e⁻² ≈ 0.135, so the current is about 13.5% of its starting value. At the same moment the charge has reached about 86.5% of its final value.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7228';
UPDATE questions SET stem = 'A proton and an alpha particle enter the same uniform magnetic field at right angles to it with equal kinetic energies. The ratio of the radii of their paths r_{p} : r_{α} is', why = 'With kinetic energy K, momentum is mv = √(2mK), so r = mv/(qB) = √(2mK)/(qB) ∝ √m/q. An alpha particle has 4 times the mass and 2 times the charge of a proton, so √4/2 = 1. The two radii are equal, r_{p} : r_{α} = 1 : 1.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7250';
UPDATE questions SET stem = 'A proton and an alpha particle enter the same uniform magnetic field at right angles to it with equal speeds. The ratio of the radii of their paths r_{p} : r_{α} is', why = 'From qvB = mv²/r, the radius is r = mv/(qB). For equal speeds in the same field, r ∝ m/q. A proton has m/q = 1 unit, while an alpha particle has 4/2 = 2 units. So r_{p} : r_{α} = 1 : 2.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7251';
UPDATE questions SET why = 'Inductive reactance is X_{L} = 2πfL and capacitive reactance is X_{C} = 1/(2πfC). Setting them equal gives f = 1/(2π√(LC)). Here LC = 0.10 × 100 × 10⁻⁶ = 10⁻⁵ s², so √(LC) ≈ 3.16 × 10⁻³ s and f ≈ 1/(2π × 3.16 × 10⁻³) ≈ 50 Hz.', wrong = '{"0": "316 is 1/√(LC), the angular frequency in rad s⁻¹. Dividing by 2π gives the frequency in Hz.", "2": "16 Hz uses LC = 10⁻⁴ s², a slip in converting 100 µF.", "3": "100 Hz does not satisfy 2πfL = 1/(2πfC). At 100 Hz X_{L} is four times X_{C}."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7274';
UPDATE questions SET options = '["V_{rms} I_{rms}", "V₀I₀/2", "V₀I₀", "zero"]', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7276';
UPDATE questions SET why = 'The reactance of a capacitor is X_{C} = 1/(2πfC), so it falls as the frequency rises. A lower reactance lets more current flow through the series circuit at the same voltage. So the lamp glows more brightly.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7277';
UPDATE questions SET stem = 'If the reverse voltage across a PN junction diode is raised beyond a certain value, a large reverse current suddenly flows. This is called', options = '["forward conduction", "rectification", "the barrier potential", "reverse breakdown"]', why = 'In reverse bias only a tiny leakage current flows. Beyond a certain reverse voltage, the breakdown voltage, the strong field across the junction frees many carriers at once and the reverse current rises sharply. This is reverse breakdown, and an ordinary diode can be damaged by it.', wrong = '{"0": "Forward conduction happens in forward bias, when the p-side is connected to the positive terminal.", "1": "Rectification is the use of diodes to change AC into DC. It is not about a sudden reverse current.", "2": "The barrier potential is the small voltage across the junction (about 0.7 V for silicon) that must be overcome in forward bias."}', topic = 'PN junction', difficulty = 'moderate', answer = 3, updated_at = unixepoch() * 1000 WHERE id = 'PHY-7284';
UPDATE questions SET stem = 'Two radioactive samples A and B start with equal numbers of nuclei. A has a half-life of 2 h and B of 4 h. After 8 h, the ratio of undecayed nuclei N_{A} : N_{B} is', why = 'In 8 h, sample A (T½ = 2 h) goes through 4 half-lives, leaving (½)⁴ = 1/16 of its nuclei. Sample B (T½ = 4 h) goes through 2 half-lives, leaving (½)² = ¼. So N_{A} : N_{B} = 1/16 : 1/4 = 1 : 4.', updated_at = unixepoch() * 1000 WHERE id = 'PHY-7298';

-- 5. New questions for the thin chapters: Electronics (PMDC, NUMS, AKU), NUMS Solids, FSc 2 Chromatography and Organic
-- synthesis, FSc 1 Special theory of relativity (CHE-2201 on, PHY-2201 on), and Army non-verbal figure matrices, paper
-- folding and cubes and dice (LR-1201 on, also in NET Intelligence). FSc Physics and Chemistry questions are listed in
-- the engineering banks too, as lib/banks.ts asks.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PHY-2201', 'Physics', 'Electronics', 'Doping', 'easy', 'Markhor Prep original question', 'Adding a very small amount of a pentavalent element such as phosphorus to pure silicon produces:', '', '["A p-type semiconductor", "An insulator", "An n-type semiconductor", "A pure (intrinsic) semiconductor"]', 2, 'Phosphorus has five valence electrons. Four of them form covalent bonds with the neighbouring silicon atoms, and the fifth is left free to move. Free electrons become the majority charge carriers, so the material is n-type.', '{"0": "A p-type semiconductor is made with a trivalent element such as boron, which leaves holes instead of free electrons.", "1": "Doping makes silicon conduct better, not worse, because it adds charge carriers.", "3": "An intrinsic semiconductor is pure. Adding phosphorus makes it extrinsic (doped)."}', 1),
  ('PHY-2202', 'Physics', 'Electronics', 'Doping', 'moderate', 'Markhor Prep original question', 'In a p-type semiconductor, the majority charge carriers are:', '', '["Free electrons", "Holes", "The dopant ions", "Protons"]', 1, 'A trivalent dopant such as boron has only three valence electrons, so one bond around each boron atom is missing an electron. These vacancies, called holes, are the majority carriers. A few free electrons are still made by heat, and they are the minority carriers.', '{"0": "Free electrons are the minority carriers in p-type material. They are the majority carriers in n-type.", "2": "The dopant ions are fixed in the crystal and cannot move, so they do not carry current.", "3": "Protons are held in the nuclei and never move through a solid."}', 1),
  ('PHY-2203', 'Physics', 'Electronics', 'PN junction', 'moderate', 'Markhor Prep original question', 'Compared with a silicon diode, a germanium diode in forward bias starts to conduct at:', '', '["A higher voltage, about 1.5 V", "A lower voltage, about 0.3 V", "The same voltage, about 0.7 V", "Zero volts, with no barrier at all"]', 1, 'The potential barrier of a germanium junction is about 0.3 V, while that of a silicon junction is about 0.7 V. So a germanium diode begins to conduct at a lower forward voltage.', '{"0": "Germanium''s barrier is lower than silicon''s, not higher.", "2": "About 0.7 V is the value for silicon. Germanium''s barrier is smaller.", "3": "Every PN junction has a barrier potential that must be overcome before a large forward current flows."}', 1),
  ('PHY-2204', 'Physics', 'Electronics', 'PN junction', 'moderate', 'Markhor Prep original question', 'A light-emitting diode (LED) gives out light when it is:', '', '["Forward biased, as electrons and holes recombine at the junction", "Reverse biased, as the depletion region widens", "Not connected, as it absorbs heat from the air", "Reverse biased beyond breakdown, as it melts"]', 0, 'In forward bias, electrons from the n-side and holes from the p-side cross into the junction and recombine. Each recombination releases energy, and in an LED that energy comes out as a photon of light.', '{"1": "In reverse bias almost no current flows, so there is no recombination and no light.", "2": "An LED needs a forward current. It does not glow by itself from the heat of the air.", "3": "Breakdown can destroy a diode. Light comes from recombination in forward bias."}', 1)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PHY-2205', 'Physics', 'Electronics', 'PN junction', 'easy', 'Markhor Prep original question', 'In the circuit symbol of a diode, the arrow (triangle) points in the direction in which:', '', '["Electrons flow when the diode is forward biased", "Current flows when the diode is reverse biased", "The depletion region grows", "Conventional current flows when the diode is forward biased"]', 3, 'The triangle of the diode symbol points from the p-side (anode) to the n-side (cathode). That is the way conventional current passes through a forward-biased diode.', '{"0": "Electrons move the opposite way to conventional current, from the n-side to the p-side.", "1": "In reverse bias almost no current flows in either direction.", "2": "The symbol shows the direction of easy current flow, not the depletion region."}', 1),
  ('PHY-2206', 'Physics', 'Electronics', 'PN junction', 'moderate', 'Markhor Prep original question', 'A diode is tested with an ohmmeter, first one way round and then the other. A working diode shows:', '', '["The same low resistance both ways", "The same very high resistance both ways", "A low resistance one way and a very high resistance the other way", "A resistance that keeps changing between zero and infinity"]', 2, 'The meter''s own battery forward biases the diode one way round, giving a low resistance, and reverse biases it the other way, giving a very high resistance. A diode conducts well in one direction only.', '{"0": "A low resistance both ways means the junction is short-circuited, so the diode is faulty.", "1": "A very high resistance both ways means the diode is open (broken).", "3": "A working diode gives two steady readings, low one way and high the other."}', 1),
  ('PHY-2207', 'Physics', 'Electronics', 'Rectification', 'moderate', 'Markhor Prep original question', 'A full-wave rectifier built with two diodes needs a transformer that is:', '', '["Step-up only, with no tapping", "Connected in reverse bias", "Built without a secondary coil", "Centre-tapped on the secondary coil"]', 3, 'In the two-diode full-wave rectifier, the secondary coil has a connection at its middle (a centre tap). Each half of the secondary feeds one diode in turn, so both halves of every cycle drive current the same way through the load. A bridge rectifier avoids the centre tap by using four diodes.', '{"0": "Whether the transformer steps up or down does not matter. The two-diode circuit needs the centre tap.", "1": "A transformer is not biased like a diode. It is the diodes that conduct in turn.", "2": "The output is taken from the secondary coil, so it cannot be left out."}', 1),
  ('CHE-2201', 'Chemistry', 'States of matter', 'Metallic solids', 'easy', 'Markhor Prep original question', 'Which property is typical of a metallic solid such as copper?', '', '["It conducts electricity in the solid state", "It is brittle and shatters when hammered", "It conducts electricity only when molten", "It has a low melting point and sublimes easily"]', 0, 'A metal is a lattice of positive ions in a sea of delocalized electrons. These electrons move freely, so metals conduct electricity as solids. The layers of ions can also slide without breaking the bonding, which makes metals malleable and ductile.', '{"1": "Brittleness is typical of ionic solids. Metals bend and flatten instead.", "2": "Ionic solids conduct only when molten or dissolved. Metals conduct as solids too.", "3": "Low melting points and easy sublimation are typical of molecular solids such as iodine."}', 1)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-2202', 'Chemistry', 'States of matter', 'Ionic crystals', 'moderate', 'Markhor Prep original question', 'Ionic crystals such as sodium chloride are brittle because, when a layer is pushed sideways:', '', '["The delocalized electrons escape from the crystal", "Covalent bonds between the ions break", "Ions of the same charge come next to each other and repel", "The ions turn into neutral atoms"]', 2, 'In an ionic crystal each ion is surrounded by ions of opposite charge. A small shift of one layer brings positive ions next to positive ions and negative next to negative. The strong repulsion splits the crystal along that plane.', '{"0": "Ionic crystals have no delocalized electrons. That is a feature of metals.", "1": "The bonding in sodium chloride is ionic, not covalent.", "3": "The ions keep their charges. It is the repulsion between like charges that cracks the crystal."}', 1),
  ('CHE-2203', 'Chemistry', 'States of matter', 'Isomorphism', 'moderate', 'Markhor Prep original question', 'Two different substances that have the same crystal structure, such as NaF and MgO, are said to be:', '', '["Polymorphous", "Allotropes", "Isomorphous", "Amorphous"]', 2, 'Isomorphism means different compounds crystallize with the same crystal form. NaF and MgO both form cubic crystals with the same arrangement of ions, because their ions are in the same ratio (1 : 1) and of similar relative sizes.', '{"0": "Polymorphism is the opposite idea: one substance that can crystallize in more than one form.", "1": "Allotropes are different forms of one element, such as diamond and graphite.", "3": "Amorphous solids have no regular crystal structure at all."}', 1),
  ('CHE-2204', 'Chemistry', 'States of matter', 'Polymorphism', 'moderate', 'Markhor Prep original question', 'Calcium carbonate occurs as calcite and as aragonite, which have different crystal forms. This is an example of:', '', '["Isomorphism", "Anisotropy", "Polymorphism", "Sublimation"]', 2, 'A single compound that can crystallize in two or more different forms shows polymorphism. Calcite and aragonite are both CaCO₃ but have different crystal structures.', '{"0": "Isomorphism is different compounds sharing one crystal form, the reverse of this case.", "1": "Anisotropy means a crystal''s properties differ in different directions. It is not about having two crystal forms.", "3": "Sublimation is a change from solid straight to gas."}', 1),
  ('CHE-2205', 'Chemistry', 'States of matter', 'Transition temperature', 'hard', 'Markhor Prep original question', 'Grey tin and white tin are two forms of tin that are in equilibrium at 13.2 °C. This temperature is called the:', '', '["Melting point", "Triple point", "Critical temperature", "Transition temperature"]', 3, 'The temperature at which two crystal forms of a substance are in equilibrium, and one changes into the other, is its transition temperature. Below 13.2 °C grey tin is the stable form; above it white tin is.', '{"0": "Both forms are solids, so this is not a change from solid to liquid.", "1": "The triple point is where solid, liquid and gas are in equilibrium together.", "2": "The critical temperature is the highest temperature at which a gas can be liquefied by pressure."}', 1)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-2206', 'Chemistry', 'States of matter', 'Crystal systems', 'moderate', 'Markhor Prep original question', 'In a cubic unit cell, the edge lengths a, b, c and the angles α, β, γ are:', '', '["a = b ≠ c and α = β = γ = 90°", "a ≠ b ≠ c and α = β = γ = 90°", "a = b = c and α = β = γ ≠ 90°", "a = b = c and α = β = γ = 90°"]', 3, 'A cube has three equal edges at right angles to each other, so the cubic system has a = b = c and α = β = γ = 90°. It is one of the seven crystal systems.', '{"0": "Two equal edges and a different third, all at 90°, describes the tetragonal system.", "1": "Three different edges at 90° describes the orthorhombic system.", "2": "Equal edges with equal angles that are not 90° describes the rhombohedral (trigonal) system."}', 1),
  ('CHE-2207', 'Chemistry', 'Experimental techniques and lab safety', 'Paper chromatography', 'easy', 'Markhor Prep original question', 'The starting line on a chromatography paper is drawn in pencil, not ink, because:', '', '["Pencil lines move up with the solvent and mark the solvent front", "Ink is too dark to see the spots against", "Pencil makes the paper absorb the solvent faster", "Ink would dissolve in the solvent and separate too, spoiling the chromatogram"]', 3, 'Ink is a mixture of dyes, so it would dissolve in the solvent and run up the paper like the sample, adding spots of its own. Graphite from a pencil does not dissolve, so the line stays where it is.', '{"0": "Pencil lines stay where they are drawn. The solvent front is marked separately after the run.", "1": "Darkness is not the problem. The ink itself would separate into coloured spots.", "2": "The pencil line has no effect on how fast the paper soaks up the solvent."}', 0),
  ('CHE-2208', 'Chemistry', 'Experimental techniques and lab safety', 'Paper chromatography', 'easy', 'Markhor Prep original question', 'When a chromatogram is set up, the solvent in the tank must be below the starting line because otherwise:', '', '["The solvent would not rise up the paper at all", "The Rf values would all become greater than 1", "The sample would dissolve into the solvent in the tank instead of moving up the paper", "The paper would act as the mobile phase"]', 2, 'If the spots sat below the solvent surface, the sample would wash off into the solvent in the tank. With the solvent below the line, it rises up the paper by capillary action and carries the sample with it.', '{"0": "The solvent still rises by capillary action whatever the starting level.", "1": "An Rf value can never be greater than 1, because a spot cannot move further than the solvent front.", "3": "The paper (with its water) is the stationary phase in every case."}', 0),
  ('CHE-2209', 'Chemistry', 'Experimental techniques and lab safety', 'Rf value', 'moderate', 'Markhor Prep original question', 'A student reports an Rf value of 1.25 for a dye. This result must be wrong because:', '', '["Rf values are always whole numbers", "A spot cannot travel further than the solvent front", "Rf values are always below 0.5", "Rf has units of cm, so it cannot be a ratio"]', 1, 'Rf = distance moved by the spot ÷ distance moved by the solvent front. The spot is carried by the solvent, so it can never get ahead of the solvent front. Rf therefore lies between 0 and 1.', '{"0": "Rf is a ratio of two distances and is usually a decimal, such as 0.45.", "2": "Rf can be anywhere from 0 to 1. Substances very soluble in the mobile phase can have Rf close to 1.", "3": "Rf is a ratio of two lengths, so the units cancel and it has none."}', 0)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-2210', 'Chemistry', 'Experimental techniques and lab safety', 'Identification', 'moderate', 'Markhor Prep original question', 'To find out whether an unknown spot on a chromatogram is caffeine, a chemist should:', '', '["Measure the size of the unknown spot", "Run the unknown with a different solvent only", "Run pure caffeine on the same paper in the same solvent and compare the Rf values", "Measure how long the solvent takes to reach the top"]', 2, 'The Rf value of a substance depends on the solvent, paper and temperature. Running a known sample of caffeine alongside the unknown, under exactly the same conditions, lets the two Rf values be compared fairly. Matching Rf values suggest the spot is caffeine.', '{"0": "The size of a spot depends mainly on how much was applied, not on what it is.", "1": "One run in a different solvent alone gives nothing known to compare with.", "3": "The time the solvent takes does not identify the substance."}', 0),
  ('CHE-2211', 'Chemistry', 'Experimental techniques and lab safety', 'Two-way chromatography', 'hard', 'Markhor Prep original question', 'Two-way (two-dimensional) paper chromatography is used when:', '', '["The sample contains only one substance", "Some spots overlap in one solvent, so the paper is turned 90° and run again in a second solvent", "The substances are gases", "The solvent front has to move faster"]', 1, 'Some substances have nearly the same Rf in one solvent, so their spots overlap. After the first run the paper is dried, turned through 90° and run in a second solvent. Substances that moved together in the first solvent usually separate in the second.', '{"0": "A single substance gives one spot and needs no further separation.", "2": "Gases are separated by gas chromatography, not on paper.", "3": "Two-way chromatography is about separating spots better, not about speed."}', 0),
  ('CHE-2212', 'Chemistry', 'Experimental techniques and lab safety', 'Column chromatography', 'hard', 'Markhor Prep original question', 'A mixture of a polar and a non-polar compound is run through a column of silica gel (polar) using a non-polar solvent. Which comes out of the column first?', '', '["The polar compound", "Both come out together", "Neither, both stay on the silica", "The non-polar compound"]', 3, 'Polar silica adsorbs polar molecules strongly and holds them back. The non-polar compound is adsorbed only weakly and dissolves well in the non-polar solvent, so it is carried through the column first.', '{"0": "The polar compound is held strongly by the polar silica, so it moves more slowly.", "1": "The two compounds are attracted to the silica to different extents, so they separate.", "2": "The non-polar compound is only weakly held and is washed through by the solvent."}', 0),
  ('CHE-2213', 'Chemistry', 'Organic chemistry', 'Chain lengthening', 'moderate', 'Markhor Prep original question', 'In organic synthesis, a halogenoalkane is often treated with KCN in ethanol mainly to:', '', '["Remove one carbon atom from the chain", "Turn the halogenoalkane into an alkene", "Add one carbon atom to the chain by forming a nitrile", "Oxidize the halogenoalkane to an aldehyde"]', 2, 'The cyanide ion replaces the halogen in a nucleophilic substitution, R–X + CN⁻ → R–CN + X⁻. The new C–C bond makes the carbon chain one atom longer. The nitrile can then be changed into a carboxylic acid or an amine.', '{"0": "The cyanide group adds a carbon. It does not remove one.", "1": "An alkene is made by elimination using alcoholic KOH, not by KCN.", "3": "KCN is a source of cyanide ions for substitution. It is not an oxidizing agent."}', 0)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-2214', 'Chemistry', 'Organic chemistry', 'Chain lengthening', 'hard', 'Markhor Prep original question', 'Which sequence converts ethanol into propanoic acid, CH₃CH₂COOH?', '', '["Ethanol → ethanal (oxidation) → ethanoic acid (oxidation)", "Ethanol → bromoethane (HBr) → propanenitrile (KCN) → propanoic acid (acid hydrolysis)", "Ethanol → ethene (conc. H₂SO₄) → ethane (H₂, Ni)", "Ethanol → bromoethane (HBr) → ethene (alcoholic KOH) → propanoic acid (KMnO₄)"]', 1, 'Propanoic acid has three carbon atoms and ethanol has two, so one carbon must be added. Ethanol is first turned into bromoethane. KCN then replaces the bromine with –CN, giving propanenitrile, CH₃CH₂CN. Hydrolysis with dilute acid changes –CN into –COOH, giving propanoic acid.', '{"0": "Oxidizing ethanol gives ethanoic acid, which still has only two carbon atoms.", "2": "This route ends in ethane and never makes an acid or adds a carbon.", "3": "Ethene has two carbon atoms, and oxidizing it cannot make a three-carbon acid."}', 0),
  ('CHE-2215', 'Chemistry', 'Organic chemistry', 'Yield', 'moderate', 'Markhor Prep original question', 'A synthesis has three steps, with yields of 80%, 75% and 50%. What is the overall yield?', '', '["30%", "68%", "50%", "205%"]', 0, 'The overall yield is the product of the yields of the steps: 0.80 × 0.75 × 0.50 = 0.30, which is 30%. This is why chemists prefer routes with fewer steps.', '{"1": "68% is the average of the three yields. Yields multiply from step to step; they are not averaged.", "2": "50% is only the lowest single step. The losses in the first two steps reduce it further.", "3": "205% adds the yields. A yield can never be more than 100%."}', 0),
  ('CHE-2216', 'Chemistry', 'Organic chemistry', 'Oxidation in synthesis', 'moderate', 'Markhor Prep original question', 'To make ethanal from ethanol using acidified potassium dichromate, the ethanal is distilled off as soon as it forms because:', '', '["Otherwise it would be oxidized further to ethanoic acid", "Ethanal is a solid and must be removed", "Distillation turns ethanol into ethanal", "Ethanal reacts with the dichromate to give back ethanol"]', 0, 'Ethanal is an intermediate oxidation product and is easily oxidized further to ethanoic acid. It boils at about 20 °C, much lower than ethanol, so distilling it off at once removes it from the oxidizing agent. Heating under reflux instead gives the acid.', '{"1": "Ethanal is a volatile liquid that boils at about 20 °C, not a solid.", "2": "Distillation only separates the ethanal. The dichromate does the oxidizing.", "3": "Dichromate is an oxidizing agent. It does not reduce ethanal back to ethanol."}', 0),
  ('CHE-2217', 'Chemistry', 'Organic chemistry', 'Oxidation in synthesis', 'moderate', 'Markhor Prep original question', 'Which conditions convert propan-1-ol fully into propanoic acid?', '', '["A little acidified K₂Cr₂O₇, distilling off the product at once", "Concentrated H₂SO₄ at 170 °C", "Hydrogen gas with a nickel catalyst", "Excess acidified K₂Cr₂O₇, heated under reflux"]', 3, 'A primary alcohol is oxidized first to an aldehyde and then to a carboxylic acid. Heating under reflux with excess oxidizing agent keeps the aldehyde in the flask until it has been oxidized all the way to propanoic acid.', '{"0": "Removing the product at once with limited oxidant stops at the aldehyde, propanal.", "1": "Hot concentrated sulfuric acid dehydrates the alcohol to an alkene, propene.", "2": "Hydrogen with nickel is used for reduction, the opposite of oxidation."}', 0)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-2218', 'Chemistry', 'Organic chemistry', 'C–C bond formation', 'moderate', 'Markhor Prep original question', 'Which reaction forms a new carbon–carbon bond?', '', '["Hydrolysis of an ester with NaOH", "Oxidation of ethanol to ethanal", "Friedel–Crafts alkylation of benzene with CH₃Cl and AlCl₃", "Nitration of benzene"]', 2, 'In Friedel–Crafts alkylation, AlCl₃ helps CH₃Cl form a methyl electrophile, which bonds to a carbon of the benzene ring. The product, methylbenzene, has a new C–C bond. Reactions like this build larger carbon skeletons in synthesis.', '{"0": "Ester hydrolysis breaks a C–O bond and makes an acid and an alcohol. No C–C bond forms.", "1": "Oxidation changes the functional group but keeps the same carbon skeleton.", "3": "Nitration forms a C–N bond, adding an –NO₂ group to the ring."}', 0),
  ('PHY-2208', 'Physics', 'Modern and nuclear physics', 'Time dilation', 'hard', 'Markhor Prep original question', 'A muon has a lifetime of 2.2 μs in its own rest frame. If it moves at 0.99c relative to the Earth, about how long does it live as measured from the Earth?', '', '["About 16 μs", "About 2.2 μs", "About 0.31 μs", "About 220 μs"]', 0, 'Time dilation: t = t₀ ÷ √(1 − v²/c²). Here √(1 − 0.99²) = √0.0199 ≈ 0.141, so t ≈ 2.2 μs ÷ 0.141 ≈ 15.6 μs, about 16 μs. This is why muons made high in the atmosphere reach the ground.', '{"1": "2.2 μs is the lifetime in the muon''s own frame. A moving clock is seen to run slow from the Earth.", "2": "0.31 μs multiplies by 0.141 instead of dividing, which would make the moving muon''s life shorter.", "3": "220 μs divides by 0.01 (1 − 0.99) instead of by the square root of 1 − 0.99²."}', 0),
  ('PHY-2209', 'Physics', 'Modern and nuclear physics', 'Length contraction', 'moderate', 'Markhor Prep original question', 'A rod is 10 m long in its own frame. It moves along its length at 0.8c past an observer. What length does the observer measure?', '', '["6 m", "8 m", "10 m", "16.7 m"]', 0, 'Length contraction: L = L₀√(1 − v²/c²) = 10 × √(1 − 0.64) = 10 × 0.6 = 6 m. Only the length along the direction of motion is shortened.', '{"1": "8 m multiplies by 0.8, the speed, instead of by √(1 − 0.8²) = 0.6.", "2": "10 m is the proper length, measured by an observer at rest with the rod.", "3": "16.7 m divides by 0.6, which would make the moving rod longer. Moving lengths are measured shorter."}', 0),
  ('PHY-2210', 'Physics', 'Modern and nuclear physics', 'Postulates of relativity', 'moderate', 'Markhor Prep original question', 'A spaceship moving at 0.5c towards the Earth switches on a forward-pointing lamp. An observer on the Earth measures the speed of the light as:', '', '["1.5c", "c", "0.5c", "2c"]', 1, 'The second postulate of special relativity says that the speed of light in a vacuum is the same, c, for all observers, whatever the motion of the source or the observer. Speeds of light do not add like the speeds of everyday objects.', '{"0": "1.5c adds the ship''s speed to the speed of light, which the second postulate rules out.", "2": "0.5c is the speed of the ship, not of the light it gives out.", "3": "Nothing can be measured moving faster than c, so 2c is impossible."}', 0)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PHY-2211', 'Physics', 'Modern and nuclear physics', 'Time dilation', 'moderate', 'Markhor Prep original question', 'One twin travels to a distant star and back at a speed close to c, while the other stays on the Earth. When they meet again:', '', '["The twin who stayed on the Earth is younger", "The travelling twin is younger", "Both twins are exactly the same age", "Neither has aged at all"]', 1, 'The travelling twin''s clocks, including the body''s own processes, run slow compared with the Earth''s during the high-speed journey. So less time passes for the traveller, who comes back younger. The traveller is the one who changes frames by turning round, so the two situations are not symmetric.', '{"0": "It is the travelling twin, not the one on the Earth, whose time runs slow over the round trip.", "2": "The two twins follow different paths through space-time, so different amounts of time pass for them.", "3": "Both twins age. The traveller simply ages less."}', 0),
  ('PHY-2212', 'Physics', 'Modern and nuclear physics', 'Relativity and everyday life', 'moderate', 'Markhor Prep original question', 'The clocks in GPS satellites have to be corrected for relativity because:', '', '["They are moving faster than light", "Light cannot travel through space", "Their mass becomes zero in orbit", "Their high speed and weaker gravity make them run at a slightly different rate from clocks on the ground"]', 3, 'Satellite clocks run slightly slow because of their speed (special relativity) and slightly fast because gravity is weaker in orbit (general relativity). The overall difference is tiny, but without correcting it GPS positions would quickly drift by kilometres.', '{"0": "Satellites move at a few kilometres per second, far below the speed of light.", "1": "Light and radio waves travel through space; that is how GPS signals reach us.", "2": "A satellite keeps its mass in orbit. Its weight is what feels smaller."}', 0),
  ('LR-1201', 'Logical Reasoning', 'Patterns and sequences', 'Figure matrices', 'easy', 'Markhor Prep original question', 'Which figure completes the grid?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''350'' height=''350'' viewBox=''0 0 350 350''><rect x=''71.0'' y=''12.0'' width=''64'' height=''64'' rx=''4'' fill=''none'' stroke=''#000'' stroke-width=''1.2''/><circle cx=''103.0'' cy=''44.0'' r=''22.3'' fill=''none'' stroke=''#000'' stroke-width=''2.2''/><circle cx=''103.0'' cy=''44.0'' r=''3.2'' fill=''#000''/><rect x=''143.0'' y=''12.0'' width=''64'' height=''64'' rx=''4'' fill=''none'' stroke=''#000'' stroke-width=''1.2''/><circle cx=''175.0'' cy=''44.0'' r=''22.3'' fill=''none'' stroke=''#000'' stroke-width=''2.2''/><circle cx=''175.0'' cy=''33.5'' r=''3.2'' fill=''#000''/><circle cx=''175.0'' cy=''54.5'' r=''3.2'' fill=''#000''/><rect x=''215.0'' y=''12.0'' width=''64'' height=''64'' rx=''4'' fill=''none'' stroke=''#000'' stroke-width=''1.2''/><circle cx=''247.0'' cy=''44.0'' r=''22.3'' fill=''none'' stroke=''#000'' stroke-width=''2.2''/><circle cx=''247.0'' cy=''33.5'' r=''3.2'' fill=''#000''/><circle cx=''237.9'' cy=''49.2'' r=''3.2'' fill=''#000''/><circle cx=''256.1'' cy=''49.2'' r=''3.2'' fill=''#000''/><rect x=''71.0'' y=''84.0'' width=''64'' height=''64'' rx=''4'' fill=''none'' stroke=''#000'' stroke-width=''1.2''/><polygon points=''82.0,137.0 124.0,137.0 124.0,95.0 82.0,95.0'' fill=''none'' stroke=''#000'' stroke-width=''2.2'' stroke-linejoin=''round'' stroke-linecap=''round''/><circle cx=''103.0'' cy=''105.5'' r=''3.2'' fill=''#000''/><circle cx=''103.0'' cy=''126.5'' r=''3.2'' fill=''#000''/><rect x=''143.0'' y=''84.0'' width=''64'' height=''64'' rx=''4'' fill=''none'' stroke=''#000'' stroke-width=''1.2''/><polygon points=''154.0,137.0 196.0,137.0 196.0,95.0 154.0,95.0'' fill=''none'' stroke=''#000'' stroke-width=''2.2'' stroke-linejoin=''round'' stroke-linecap=''round''/><circle cx=''175.0'' cy=''105.5'' r=''3.2'' fill=''#000''/><circle cx=''1