238.0'' width=''64'' height=''64'' rx=''4'' fill=''none'' stroke=''#000'' stroke-width=''1.2''/><polygon points=''215.0,247.7 193.8,263.1 201.9,288.0 228.1,288.0 236.2,263.1'' fill=''none'' stroke=''#000'' stroke-width=''2.2'' stroke-linejoin=''round'' stroke-linecap=''round''/><circle cx=''215.0'' cy=''270.0'' r=''3.2'' fill=''#000''/><text x=''215.0'' y=''318.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''15'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-weight=''bold''>C</text><rect x=''263.0'' y=''238.0'' width=''64'' height=''64'' rx=''4'' fill=''none'' stroke=''#000'' stroke-width=''1.2''/><polygon points=''295.0,247.7 275.7,258.8 275.7,281.2 295.0,292.3 314.3,281.2 314.3,258.8'' fill=''none'' stroke=''#000'' stroke-width=''2.2'' stroke-linejoin=''round'' stroke-linecap=''round''/><circle cx=''295.0'' cy=''270.0'' r=''3.2'' fill=''#000''/><text x=''295.0'' y=''318.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''15'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-weight=''bold''>D</text></svg>', '["Figure A", "Figure B", "Figure C", "Figure D"]', 2, 'Each column has one shape (triangle, square, pentagon), and each row has one style: empty, shaded, then empty with a dot in the middle. The empty cell is in the pentagon column and the dotted row.', '{"0": "The pentagon is right, but the bottom row has a dot inside an unshaded shape, not shading.", "1": "The dot is right, but the third column is all pentagons.", "3": "The dot is right, but this shape has six sides. The third column has five."}', 1)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
