-- 4. Free questions back to 100 in total (0043's 90 plus 0058's 10 Mathematics made 110): one fewer from the
-- chapters with the most free questions, 5 Biology, 3 Chemistry and 2 Physics.
UPDATE questions SET free = 0 WHERE id IN ('BIO-5101', 'BIO-1524', 'BIO-7095', 'BIO-5067', 'BIO-7143', 'CHE-6077', 'CHE-6101', 'CHE-6025', 'PHY-1530', 'PHY-7214');

-- 6. FSc 1 and FSc 2 English: their chapters were empty. They now use the MDCAT English set in the same chapters.
INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT b.bank, q.id, 'English', q.chapter FROM questions q, (SELECT 'fsc1' AS bank UNION ALL SELECT 'fsc2') b
WHERE q.subject = 'English' AND q.id LIKE 'ENG-%';

-- 7. The one open report (LR-0191, "more than one answer is correct"): checked, only R fits all the clues.
UPDATE reports SET status = 'dismissed', note = 'Checked: only R satisfies every clue, so the key is right and only one answer fits.',
  resolved_by = (SELECT id FROM users WHERE email = 'hozaiphaa@gmail.com'), resolved_at = unixepoch() * 1000
WHERE question_id = 'LR-0191' AND status = 'open';
